def _serialize_snapshot_lines(lines: list[dict[str, Any]]) -> list[dict[str, Any]]:
    serialized: list[dict[str, Any]] = []
    for line in lines or []:
        if not isinstance(line, dict):
            continue
        line_date = line.get("date")
        serialized.append(
            {
                "id": str(line.get("id") or "").strip() or None,
                "line_id": str(line.get("line_id") or "").strip() or None,
                "date": line_date.isoformat() if isinstance(line_date, date) else None,
                "daypart": line.get("daypart"),
                "menu_name": line.get("menu_name"),
                "diet_type": line.get("diet_type"),
                "area_id": line.get("area_id"),
                "bag_type": line.get("bag_type"),
                "quantity_original": line.get("quantity_original"),
                "quantity_corrected": line.get("quantity_corrected"),
                "change_note": line.get("change_note"),
                "source_row_index": line.get("source_row_index"),
            }
        )
    return serialized


class ConfirmMaterializationError(Exception):
    def __init__(self, code: str, message: str | None = None):
        super().__init__(message or code)
        self.code = str(code or "").strip() or "confirm_materialization_failed"
        self.message = str(message or "").strip() or self.code


def _build_materialization_candidate_from_draft_record(
    order_id: str,
    *,
    draft_record: dict[str, Any] | None,
    facility_id: str | None,
    existing_week_code: str | None,
    received_at: datetime | None,
) -> dict[str, Any] | None:
    if not isinstance(draft_record, dict):
        return {
            "source": "draft_sheet",
            "draft_id": None,
            "error": "draft_missing",
            "line_count": 0,
            "lines": [],
        }
    draft_sheet = draft_record.get("draft_sheet_json")
    if not isinstance(draft_sheet, dict):
        return None
    rows_payload = draft_sheet.get("rows")
    if not isinstance(rows_payload, list) or not rows_payload:
        return {
            "source": "draft_sheet",
            "draft_id": draft_record.get("id"),
            "error": "draft_rows_empty",
            "line_count": 0,
            "lines": [],
        }
    facility_config, template, _template_id, template_error = _resolve_effective_sheet_template(
        order_id=order_id,
        facility_id=facility_id,
        log_context="Facility config lookup failed during materialization candidate build",
    )
    if not facility_config:
        return {
            "source": "draft_sheet",
            "draft_id": draft_record.get("id"),
            "error": "facility_not_found",
            "line_count": 0,
            "lines": [],
        }
    if not isinstance(template, dict):
        return {
            "source": "draft_sheet",
            "draft_id": draft_record.get("id"),
            "error": template_error or "template_unresolved",
            "line_count": 0,
            "lines": [],
        }
    effective_rows_payload = _apply_expanded_cell_copy_to_materialization_rows_payload(
        fields=draft_sheet.get("fields"),
        rows_payload=rows_payload,
        facility_config=facility_config,
        week_sheet_name=_week_sheet_name_from_week_value(existing_week_code),
    )
    policy = config_service.load_ingest_policy()
    effective_received_at = received_at or datetime.utcnow()
    semantic_materialization_supported = _draft_sheet_supports_direct_materialization(
        fields=draft_sheet.get("fields"),
        rows_payload=effective_rows_payload,
    )
    candidate_lines = _build_materialization_lines_from_sheet_rows(
        fields=draft_sheet.get("fields"),
        rows_payload=effective_rows_payload,
        received_at=effective_received_at,
    )
    if semantic_materialization_supported and not candidate_lines:
        return {
            "source": "draft_sheet",
            "draft_id": draft_record.get("id"),
            "error": "draft_semantic_materialization_failed",
            "line_count": 0,
            "lines": [],
        }
    if not candidate_lines:
        parsed_rows = _normalize_structured_rows(
            header=draft_sheet.get("header"),
            rows_payload=effective_rows_payload,
            template=template,
        )
        if not parsed_rows:
            return {
                "source": "draft_sheet",
                "draft_id": draft_record.get("id"),
                "error": "draft_rows_unparseable",
                "line_count": 0,
                "lines": [],
            }
        candidate_lines = parse_order_lines(
            parsed_rows,
            template,
            effective_received_at,
            policy.get("quantity_rules", {}),
        )
    if not candidate_lines:
        return {
            "source": "draft_sheet",
            "draft_id": draft_record.get("id"),
            "error": "draft_lines_empty",
            "line_count": 0,
            "lines": [],
        }
    candidate_lines = _apply_change_override_priority_to_lines(candidate_lines)

    facility_week_hint = None
    global_week_hint = None
    if facility_id:
        with session_scope() as session:
            facility_week_hint = (
                session.execute(
                    select(Order.week_code)
                    .where(Order.facility_code == facility_id, Order.week_code.is_not(None))
                    .order_by(Order.received_at.desc())
                    .limit(1)
                )
                .scalars()
                .first()
            )
            global_week_hint = (
                session.execute(
                    select(Order.week_code)
                    .where(Order.week_code.is_not(None))
                    .order_by(Order.received_at.desc())
                    .limit(1)
                )
                .scalars()
                .first()
            )

    week_resolution_lines: list[dict[str, Any]] = []
    for line in candidate_lines:
        if not isinstance(line, dict):
            continue
        normalized = dict(line)
        normalized["date"] = _parse_date_value(normalized.get("date"))
        week_resolution_lines.append(normalized)
    line_dates = [
        line.get("date")
        for line in week_resolution_lines
        if isinstance(line.get("date"), date)
    ]
    derived_week_id = (
        month_id_from_dates(line_dates, effective_received_at, policy) if line_dates else None
    )
    ocr_payload_for_week: dict[str, Any] | None = None
    payload_for_week, _ = _get_ocr_output_without_legacy_edits(order_id, persist_cache=False)
    if isinstance(payload_for_week, dict):
        ocr_payload_for_week = payload_for_week
    min_ratio = float(policy.get("menu_match_min_ratio", 0.72))
    draft_week_id = str(
        draft_sheet.get("resolved_week_id") or draft_sheet.get("week_id") or ""
    ).strip() or None
    week_id = draft_week_id or _resolve_sheet_week_id(
        current_week_id=existing_week_code,
        received_at=effective_received_at,
        order_lines=week_resolution_lines,
        ocr_payload=ocr_payload_for_week,
        facility_id=facility_id,
        week_hints=[hint for hint in [facility_week_hint, global_week_hint] if hint],
    )
    if not week_id:
        week_id = _prefer_existing_week_when_derived_missing_menu(
            derived_week_id=derived_week_id,
            existing_week_code=existing_week_code,
            facility_id=facility_id,
        )
    payload_dates_for_position = _collect_sheet_dates_from_rows(
        effective_rows_payload,
        received_at=effective_received_at,
    )
    if isinstance(ocr_payload_for_week, dict):
        payload_dates_for_position |= {
            item
            for item in _collect_sheet_dates_from_payload(ocr_payload_for_week, effective_received_at)
            if isinstance(item, date)
        }
    position_entries_for_apply = _build_position_entries_for_lines(
        week_id=week_id,
        lines=week_resolution_lines,
        payload_dates=payload_dates_for_position,
    )
    enable_position_mapping = bool(template.get("map_menu_by_position", True))
    mapped_rows = 0
    if enable_position_mapping:
        candidate_lines, mapped_rows = _apply_menu_position_mapping_safe(
            candidate_lines,
            week_id,
            facility_id=facility_id,
            entries_override=position_entries_for_apply if position_entries_for_apply else None,
        )
    if mapped_rows <= 0:
        candidate_lines = _apply_menu_matching(candidate_lines, week_id, facility_id, min_ratio)

    materialization_guard = _build_materialization_quantity_guard_detail(
        fields=draft_sheet.get("fields"),
        rows_payload=effective_rows_payload,
        candidate_lines=candidate_lines,
    )
    if isinstance(materialization_guard, dict):
        logger.error(
            "Draft sheet materialization guard rejected candidate lines",
            order_id=order_id,
            facility_id=facility_id,
            draft_id=draft_record.get("id"),
            mismatch_count=materialization_guard.get("mismatch_count"),
            mismatches=materialization_guard.get("mismatches"),
        )
        return {
            "source": "draft_sheet",
            "draft_id": draft_record.get("id"),
            "draft_state": draft_record.get("draft_state"),
            "line_count": 0,
            "lines": [],
            "derived_week_code": week_id or derived_week_id or existing_week_code,
            "error": "draft_materialization_mismatch",
            "materialization_guard": materialization_guard,
        }

    serialized_lines = _serialize_snapshot_lines(candidate_lines)
    return {
        "source": "draft_sheet",
        "draft_id": draft_record.get("id"),
        "draft_state": draft_record.get("draft_state"),
        "line_count": len(serialized_lines),
        "lines": serialized_lines,
        "derived_week_code": week_id or derived_week_id or existing_week_code,
        "error": None if serialized_lines else "draft_lines_empty",
    }


def _parse_materialization_quantity_cell(value: object) -> float | None:
    if value is None:
        return None
    text = str(value).strip()
    if not text:
        return None
    normalized = (
        text.replace("<br>", " ")
        .replace("<br/>", " ")
        .replace("<br />", " ")
        .translate(_SHEET_TRANSLATION)
    )
    compact = re.sub(r"[\s　]+", "", normalized)
    compact = compact.replace(",", "").replace("，", "")
    compact = compact.replace("．", ".").replace("。", ".")
    compact = compact.strip("()[]（）")
    if re.fullmatch(r"-?\d+\.", compact):
        compact = compact[:-1]
    if not re.fullmatch(r"-?\d+(?:\.\d+)?", compact):
        return None
    try:
        parsed = float(compact)
    except Exception:
        return None
    if parsed < 0:
        return None
    if not parsed.is_integer():
        if re.fullmatch(r"\d\.\d", compact):
            parsed = float(compact.replace(".", ""))
        else:
            return None
    return parsed


def _normalize_materialization_signature_quantity(value: object) -> int | float | None:
    if value is None:
        return None
    parsed: float | None
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            parsed = float(value)
        except Exception:
            return None
    else:
        parsed = _parse_materialization_quantity_cell(value)
    if parsed is None or parsed < 0:
        return None
    return int(parsed) if float(parsed).is_integer() else float(parsed)


def _normalize_materialization_row_values(
    *,
    fields: list[str],
    row: object,
) -> list[str]:
    if isinstance(row, list):
        values = [_coerce_table_cell(cell) for cell in row]
    elif isinstance(row, dict):
        values = [_coerce_table_cell(row.get(field)) for field in fields]
    else:
        return []
    if len(values) < len(fields):
        values = values + [""] * (len(fields) - len(values))
    return values


def _apply_expanded_cell_copy_to_materialization_rows_payload(
    *,
    fields: object,
    rows_payload: object,
    facility_config: dict[str, Any] | None,
    week_sheet_name: str | None = None,
) -> object:
    if not _expanded_cell_same_daypart_copy_enabled(
        facility_config,
        week_sheet_name=week_sheet_name,
    ):
        return rows_payload
    if not isinstance(fields, list) or not isinstance(rows_payload, list) or not rows_payload:
        return rows_payload
    normalized_fields = [str(field or "").strip() for field in fields if str(field or "").strip()]
    if not normalized_fields or _draft_fields_look_generic(normalized_fields):
        return rows_payload
    quantity_index = _build_sheet_quantity_index(normalized_fields)
    if not quantity_index:
        return rows_payload

    normalized_rows: list[dict[str, Any]] = []
    for row in rows_payload:
        values = _normalize_materialization_row_values(fields=normalized_fields, row=row)
        if not values:
            values = [""] * len(normalized_fields)
        normalized_rows.append({"values": values})
    filled = _apply_expanded_cell_same_daypart_copy(
        rows=normalized_rows,
        fields=normalized_fields,
        quantity_index=quantity_index,
    )
    if filled <= 0:
        return rows_payload
    return [list(row.get("values") or []) for row in normalized_rows]


def _build_materialization_lines_from_sheet_rows(
    *,
    fields: object,
    rows_payload: object,
    received_at: datetime,
) -> list[dict[str, Any]]:
    if not isinstance(fields, list) or not isinstance(rows_payload, list):
        return []
    normalized_fields = [str(field or "").strip() for field in fields if str(field or "").strip()]
    if not normalized_fields or _draft_fields_look_generic(normalized_fields):
        return []

    date_idx, daypart_idx, menu_idx, _ = _resolve_structural_row_field_indexes(normalized_fields)
    quantity_index = _build_sheet_quantity_index(normalized_fields)
    if menu_idx is None or not quantity_index:
        return []

    note_idx = (
        normalized_fields.index("remarks")
        if "remarks" in normalized_fields
        else (normalized_fields.index("note") if "note" in normalized_fields else None)
    )
    latest_resolved_date: date | None = None
    first_date_in_table: date | None = None
    materialized_lines: list[dict[str, Any]] = []

    for row_index, row in enumerate(rows_payload):
        values = _normalize_materialization_row_values(fields=normalized_fields, row=row)
        if not values:
            continue

        raw_date = values[date_idx] if date_idx is not None and date_idx < len(values) else ""
        parsed_date = _extract_entry_date_from_sheet_cell(raw_date, received_at)
        if parsed_date is None:
            parsed_date = _infer_following_date_from_weekday_hint(latest_resolved_date, raw_date)
        if parsed_date is None and not str(raw_date or "").strip():
            parsed_date = latest_resolved_date or first_date_in_table
        if isinstance(parsed_date, date):
            latest_resolved_date = parsed_date
            if first_date_in_table is None:
                first_date_in_table = parsed_date

        raw_daypart = values[daypart_idx] if daypart_idx is not None and daypart_idx < len(values) else ""
        daypart = _normalize_daypart_key(raw_daypart)
        raw_menu = values[menu_idx] if menu_idx < len(values) else ""
        menu_name = str(raw_menu or "").strip()
        change_note = str(values[note_idx] or "").strip() if note_idx is not None and note_idx < len(values) else ""

        if not isinstance(parsed_date, date) or not daypart or not menu_name:
            continue

        for (diet_key, area_key), col_idx in quantity_index.items():
            if col_idx < 0 or col_idx >= len(values):
                continue
            qty = _parse_materialization_quantity_cell(values[col_idx])
            if qty is None:
                continue
            materialized_lines.append(
                {
                    "date": parsed_date,
                    "daypart": daypart,
                    "menu_name": menu_name,
                    "diet_type": diet_key,
                    "area_id": area_key,
                    "bag_type": None,
                    "quantity_original": int(qty) if float(qty).is_integer() else qty,
                    "quantity_corrected": None,
                    "change_note": change_note or None,
                    "source_row_index": row_index,
                }
            )

    return _apply_change_override_priority_to_lines(materialized_lines)


def _regular_override_priority(diet_type: object) -> int:
    normalized = _normalize_sheet_diet(diet_type)
    if normalized == "change_2":
        return 2
    if normalized == "change_1":
        return 1
    if normalized == "regular":
        return 0
    return -1


def _build_change_override_group_key(line: dict[str, Any]) -> tuple[object, ...] | None:
    if not isinstance(line, dict):
        return None
    diet_key = _normalize_sheet_diet(line.get("diet_type"))
    if diet_key not in {"regular", "change_1", "change_2"}:
        return None
    source_row_raw = line.get("source_row_index")
    try:
        source_row_index = int(source_row_raw) if source_row_raw is not None else None
    except Exception:
        source_row_index = None
    return (
        source_row_index if source_row_index is not None and source_row_index >= 0 else None,
        _normalize_bag_summary_date(line.get("date")),
        _normalize_daypart_key(line.get("daypart")),
        _normalize_sheet_text(line.get("menu_name")),
        _normalize_sheet_area(line.get("area_id")) or "X",
        _normalize_sheet_text(line.get("bag_type")).lower(),
    )


def _apply_change_override_priority_to_lines(
    lines: list[dict[str, Any]] | None,
) -> list[dict[str, Any]]:
    if not isinstance(lines, list) or not lines:
        return []

    grouped: dict[tuple[object, ...], list[tuple[int, dict[str, Any]]]] = {}
    ordered_group_keys: list[tuple[object, ...]] = []
    passthrough: list[tuple[int, dict[str, Any]]] = []

    for idx, line in enumerate(lines):
        if not isinstance(line, dict):
            continue
        group_key = _build_change_override_group_key(line)
        if group_key is None:
            passthrough.append((idx, line))
            continue
        bucket = grouped.setdefault(group_key, [])
        if not bucket:
            ordered_group_keys.append(group_key)
        bucket.append((idx, line))

    collapsed: list[tuple[int, dict[str, Any]]] = list(passthrough)
    for group_key in ordered_group_keys:
        entries = grouped.get(group_key) or []
        if not entries:
            continue
        by_diet: dict[str, list[tuple[int, dict[str, Any]]]] = {}
        for idx, line in entries:
            diet_key = _normalize_sheet_diet(line.get("diet_type"))
            if not diet_key:
                continue
            by_diet.setdefault(diet_key, []).append((idx, line))
        # If the same override diet appears multiple times for the same group,
        # the relationship is ambiguous. Keep the original lines untouched.
        if any(len(bucket) > 1 for bucket in by_diet.values()):
            collapsed.extend(entries)
            continue
        selected: tuple[int, dict[str, Any]] | None = None
        for diet_key in ("change_2", "change_1", "regular"):
            bucket = by_diet.get(diet_key) or []
            if bucket:
                selected = bucket[0]
                break
        if selected is None:
            collapsed.extend(entries)
            continue
        _, selected_line = selected
        normalized = dict(selected_line)
        normalized["diet_type"] = "regular"
        collapsed.append((min(idx for idx, _ in entries), normalized))

    collapsed.sort(key=lambda item: item[0])
    return [dict(line) for _, line in collapsed]


def _apply_change_override_priority_to_quantity_summary(
    summary: dict[tuple[int, str, str], float],
) -> dict[tuple[int, str, str], float]:
    if not summary:
        return {}

    regular_like: dict[tuple[int, str], dict[str, float]] = {}
    normalized: dict[tuple[int, str, str], float] = {}

    for (row_index, diet_key, area_key), qty in summary.items():
        normalized_diet = _normalize_sheet_diet(diet_key) or str(diet_key or "").strip()
        normalized_area = _normalize_sheet_area(area_key) or "X"
        if normalized_diet in {"regular", "change_1", "change_2"}:
            bucket = regular_like.setdefault((row_index, normalized_area), {})
            bucket[normalized_diet] = float(qty)
            continue
        normalized[(row_index, normalized_diet, normalized_area)] = float(qty)

    for (row_index, area_key), bucket in regular_like.items():
        effective_qty = (
            bucket.get("change_2")
            if bucket.get("change_2") is not None
            else bucket.get("change_1")
            if bucket.get("change_1") is not None
            else bucket.get("regular")
        )
        if effective_qty is None:
            continue
        normalized[(row_index, "regular", area_key)] = float(effective_qty)

    return normalized


def _draft_sheet_supports_direct_materialization(
    *,
    fields: object,
    rows_payload: object,
) -> bool:
    if not isinstance(fields, list) or not isinstance(rows_payload, list) or not rows_payload:
        return False
    normalized_fields = [str(field or "").strip() for field in fields if str(field or "").strip()]
    if not normalized_fields or _draft_fields_look_generic(normalized_fields):
        return False
    _, _, menu_idx, _ = _resolve_structural_row_field_indexes(normalized_fields)
    quantity_index = _build_sheet_quantity_index(normalized_fields)
    return menu_idx is not None and bool(quantity_index)


def _build_sheet_source_row_quantity_summary(
    *,
    fields: object,
    rows_payload: object,
) -> dict[tuple[int, str, str], float]:
    if not isinstance(fields, list) or not isinstance(rows_payload, list):
        return {}
    normalized_fields = [str(field or "").strip() for field in fields if str(field or "").strip()]
    if not normalized_fields or _draft_fields_look_generic(normalized_fields):
        return {}
    quantity_index = _build_sheet_quantity_index(normalized_fields)
    if not quantity_index:
        return {}

    summary: dict[tuple[int, str, str], float] = {}
    for row_index, row in enumerate(rows_payload):
        values = _normalize_materialization_row_values(fields=normalized_fields, row=row)
        if not values:
            continue
        for (diet_key, area_key), col_idx in quantity_index.items():
            if col_idx < 0 or col_idx >= len(values):
                continue
            qty = _parse_materialization_quantity_cell(values[col_idx])
            if qty is None:
                continue
            key = (row_index, diet_key, area_key)
            summary[key] = summary.get(key, 0.0) + float(qty)
    return summary


def _build_materialized_source_row_quantity_summary(
    lines: list[dict[str, Any]] | None,
) -> dict[tuple[int, str, str], float]:
    summary: dict[tuple[int, str, str], float] = {}
    for line in lines or []:
        if not isinstance(line, dict):
            continue
        source_row_raw = line.get("source_row_index")
        try:
            source_row_index = int(source_row_raw) if source_row_raw is not None else None
        except Exception:
            source_row_index = None
        if source_row_index is None or source_row_index < 0:
            continue
        diet_key = _normalize_sheet_diet(line.get("diet_type"))
        area_key = _normalize_sheet_area(line.get("area_id"))
        if not diet_key or not area_key:
            continue
        qty = line.get("quantity_corrected")
        if qty is None:
            qty = line.get("quantity_original")
        try:
            qty_value = float(qty)
        except Exception:
            continue
        key = (source_row_index, diet_key, area_key)
        summary[key] = summary.get(key, 0.0) + qty_value
    return summary


def _build_materialization_quantity_guard_detail(
    *,
    fields: object,
    rows_payload: object,
    candidate_lines: list[dict[str, Any]] | None,
) -> dict[str, Any] | None:
    expected = _apply_change_override_priority_to_quantity_summary(
        _build_sheet_source_row_quantity_summary(fields=fields, rows_payload=rows_payload)
    )
    if not expected:
        return None
    actual = _apply_change_override_priority_to_quantity_summary(
        _build_materialized_source_row_quantity_summary(candidate_lines)
    )

    mismatches: list[dict[str, Any]] = []
    for row_index, diet_key, area_key in sorted(set(expected) | set(actual)):
        expected_qty = expected.get((row_index, diet_key, area_key), 0.0)
        actual_qty = actual.get((row_index, diet_key, area_key), 0.0)
        if abs(expected_qty - actual_qty) <= 1e-6:
            continue
        mismatches.append(
            {
                "source_row_index": row_index,
                "diet_type": diet_key,
                "area_id": area_key,
                "expected_quantity": expected_qty,
                "actual_quantity": actual_qty,
            }
        )
    if not mismatches:
        return None
    return {
        "actual_summary_missing": not actual,
        "mismatch_count": len(mismatches),
        "mismatches": mismatches[:40],
    }


def _build_confirm_materialization_candidate_from_draft(
    order_id: str,
    *,
    facility_id: str | None,
    existing_week_code: str | None,
    received_at: datetime | None,
) -> dict[str, Any] | None:
    current_sheet_context = get_current_sheet_context(
        order_id,
        refresh_draft_from_semantic=True,
        upgrade_generic_from_sheet=True,
        backfill_from_revision=False,
    )
    latest_draft = (
        current_sheet_context.get("draft_record")
        if isinstance(current_sheet_context, dict)
        else None
    )
    return _build_materialization_candidate_from_draft_record(
        order_id,
        draft_record=latest_draft,
        facility_id=facility_id,
        existing_week_code=existing_week_code,
        received_at=received_at,
    )


def build_confirm_materialization_candidate(order_id: str) -> dict[str, Any] | None:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None
        return _build_confirm_materialization_candidate_from_draft(
            order_id,
            facility_id=order.facility_code,
            existing_week_code=order.week_code,
            received_at=order.received_at or datetime.utcnow(),
        )


def _persist_confirmed_snapshot(
    order_id: str,
    *,
    confirmed_by: str | None = None,
    materialization_candidate: dict[str, Any] | None = None,
    materialized_lines: list[dict[str, Any]] | None = None,
) -> str | None:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None
        resolved_candidate = materialization_candidate or _build_confirm_materialization_candidate_from_draft(
            order_id,
            facility_id=order.facility_code,
            existing_week_code=order.week_code,
            received_at=order.received_at or datetime.utcnow(),
        )
        snapshot_lines = (
            _serialize_snapshot_lines(materialized_lines)
            if isinstance(materialized_lines, list)
            else _serialize_snapshot_lines(
                [
                    dict(
                        id=line.id,
                        line_id=line.line_id,
                        date=line.date,
                        daypart=line.daypart,
                        menu_name=line.menu_name,
                        diet_type=line.diet_type,
                        area_id=line.area_id,
                        bag_type=line.bag_type,
                        quantity_original=line.quantity_original,
                        quantity_corrected=line.quantity_corrected,
                        change_note=line.change_note,
                    )
                    for line in (order.lines or [])
                ]
            )
        )
        snapshot_json = {
            "order_id": order.id,
            "facility": order.facility_code,
            "week": order.week_code,
            "status": order.status,
            "lines_updated_at": order.lines_updated_at.isoformat() if isinstance(order.lines_updated_at, datetime) else None,
            "lines": snapshot_lines,
            "materialization_candidate": resolved_candidate,
        }
        snapshot_digest = hashlib.sha256(json.dumps(snapshot_json, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
        snapshot = OrderConfirmedSnapshot(
            id=f"OCS{uuid4().hex[:12]}",
            order_id=order.id,
            draft_id=(get_latest_sheet_draft(order_id, backfill_from_revision=False) or {}).get("id"),
            snapshot_digest=snapshot_digest,
            snapshot_json=snapshot_json,
            confirmed_by=str(confirmed_by or "").strip() or None,
        )
        session.add(snapshot)
        session.flush()
        return snapshot.id


def _materialize_confirmed_lines_from_candidate(
    session,
    order: Order,
    candidate: dict[str, Any] | None,
) -> bool:
    if not isinstance(candidate, dict):
        raise ConfirmMaterializationError(
            "draft_missing",
            "latest draft is required before confirm",
        )
    candidate_error = str(candidate.get("error") or "").strip()
    if candidate_error:
        raise ConfirmMaterializationError(
            candidate_error,
            f"latest draft cannot be confirmed: {candidate_error}",
        )
    serialized_lines = candidate.get("lines")
    if not isinstance(serialized_lines, list) or not serialized_lines:
        raise ConfirmMaterializationError(
            "draft_lines_empty",
            "latest draft does not contain any materializable lines",
        )

    materialized_lines: list[dict[str, Any]] = []
    for line in serialized_lines:
        if not isinstance(line, dict):
            continue
        materialized_lines.append(
            {
                "id": str(line.get("id") or "").strip() or None,
                "line_id": str(line.get("line_id") or "").strip() or None,
                "date": _parse_date_value(line.get("date")),
                "daypart": line.get("daypart"),
                "menu_name": line.get("menu_name"),
                "diet_type": line.get("diet_type"),
                "area_id": line.get("area_id"),
                "bag_type": line.get("bag_type"),
                "quantity_original": line.get("quantity_original"),
                "quantity_corrected": line.get("quantity_corrected"),
                "change_note": line.get("change_note"),
            }
        )
    if not materialized_lines:
        raise ConfirmMaterializationError(
            "draft_lines_empty",
            "latest draft does not contain any materializable lines",
        )

    normalized_lines = _ensure_unique_line_ids(materialized_lines, exclude_order_id=order.id)
    session.execute(delete(OrderLine).where(OrderLine.order_id == order.id))
    for line in normalized_lines:
        session.add(
            OrderLine(
                id=line.get("id") or _make_line_id(),
                order_id=order.id,
                line_id=line.get("line_id"),
                date=_parse_date_value(line.get("date")),
                daypart=line.get("daypart"),
                menu_name=line.get("menu_name"),
                diet_type=line.get("diet_type"),
                area_id=line.get("area_id"),
                bag_type=line.get("bag_type"),
                quantity_original=line.get("quantity_original"),
                quantity_corrected=line.get("quantity_corrected"),
                change_note=line.get("change_note"),
            )
        )
    derived_week_code = _normalize_auto_week_value_for_order(order, candidate.get("derived_week_code")) or str(
        candidate.get("derived_week_code") or ""
    ).strip()
    if derived_week_code:
        _apply_system_managed_order_week_code(order, derived_week_code)
    order.lines_updated_at = datetime.utcnow()
    return True


def _serialize_order_lines_for_digest(lines: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        {
            "date": (
                line.get("date").isoformat()
                if isinstance(line.get("date"), date)
                else line.get("date")
            ),
            "daypart": line.get("daypart"),
            "menu_name": line.get("menu_name"),
            "diet_type": line.get("diet_type"),
            "area_id": line.get("area_id"),
            "bag_type": line.get("bag_type"),
            "quantity_original": line.get("quantity_original"),
            "quantity_corrected": line.get("quantity_corrected"),
            "change_note": line.get("change_note"),
        }
        for line in lines
        if isinstance(line, dict)
    ]


def apply_latest_draft(
    order_id: str,
    *,
    draft_record: dict[str, Any] | None = None,
    source: str = "draft_sheet",
    expected_lines_updated_at: str | None = None,
    enforce_lines_guard: bool = False,
) -> tuple[dict[str, Any] | None, str | None]:
    serialized_order: dict[str, Any] | None = None
    materialization_candidate: dict[str, Any] | None = None
    before_count = 0
    after_count = 0
    before_digest = ""
    after_digest = ""
    facility_code: str | None = None
    week_code: str | None = None

    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        if enforce_lines_guard:
            lines_conflict = _lines_timestamp_conflict_detail(
                current_lines_updated_at=order.lines_updated_at,
                expected_lines_updated_at=expected_lines_updated_at,
            )
            if lines_conflict is not None:
                return None, lines_conflict["error"]
        existing_lines = session.execute(
            select(OrderLine).where(OrderLine.order_id == order_id)
        ).scalars().all()
        before_count = len(existing_lines)
        before_digest = _line_digest(
            [
                {
                    "date": line.date.isoformat() if line.date else None,
                    "daypart": line.daypart,
                    "menu_name": line.menu_name,
                    "diet_type": line.diet_type,
                    "area_id": line.area_id,
                    "bag_type": line.bag_type,
                    "quantity_original": line.quantity_original,
                    "quantity_corrected": line.quantity_corrected,
                    "change_note": line.change_note,
                }
                for line in existing_lines
            ]
        )
        materialization_candidate = (
            _build_materialization_candidate_from_draft_record(
                order_id,
                draft_record=draft_record,
                facility_id=order.facility_code,
                existing_week_code=order.week_code,
                received_at=order.received_at or datetime.utcnow(),
            )
            if isinstance(draft_record, dict)
            else _build_confirm_materialization_candidate_from_draft(
                order_id,
                facility_id=order.facility_code,
                existing_week_code=order.week_code,
                received_at=order.received_at or datetime.utcnow(),
            )
        )
        try:
            _materialize_confirmed_lines_from_candidate(session, order, materialization_candidate)
        except ConfirmMaterializationError as exc:
            return None, exc.code
        session.flush()
        session.expire(order, ["lines"])
        materialized_lines = [
            {
                "id": line.id,
                "line_id": line.line_id,
                "date": line.date,
                "daypart": line.daypart,
                "menu_name": line.menu_name,
                "diet_type": line.diet_type,
                "area_id": line.area_id,
                "bag_type": line.bag_type,
                "quantity_original": line.quantity_original,
                "quantity_corrected": line.quantity_corrected,
                "change_note": line.change_note,
            }
            for line in (order.lines or [])
        ]
        after_count = len(materialized_lines)
        after_digest = _line_digest(_serialize_order_lines_for_digest(materialized_lines))
        session.refresh(order)
        facility_code = order.facility_code
        week_code = order.week_code
        serialized_order = serialize_order(order)

    record_event(
        "order_reparse",
        actor="system",
        target=order_id,
        fac=facility_code,
        wek=week_code,
        metadata={"line_count": after_count, "source": source, "mode": "apply_latest_draft"},
    )
    update_job(
        f"OCR-{order_id}",
        status="done",
        error_message=None,
        metrics={
            "source": source,
            "materialized_source": "draft_sheet",
            "draft_id": (materialization_candidate or {}).get("draft_id"),
        },
    )
    if isinstance(serialized_order, dict):
        serialized_order["reparse"] = {
            "before_count": before_count,
            "after_count": after_count,
            "before_digest": before_digest,
            "after_digest": after_digest,
            "provider": source,
            "materialized_source": "draft_sheet",
            "changed": before_digest != after_digest,
        }
        serialized_order["ocr_job_id"] = f"OCR-{order_id}"
    _invalidate_current_sheet_state_after_order_lines_write(order_id)
    try:
        _acknowledge_current_candidate_after_authoritative_action(
            order_id,
            selected_by="apply-latest-draft",
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Workflow state refresh failed after draft apply", order_id=order_id, error=str(exc))
    return serialized_order, None


def finalize_confirmed_order(postprocess_payload: dict[str, Any] | None) -> None:
    if not isinstance(postprocess_payload, dict):
        return
    order_id = str(postprocess_payload.get("order_id") or "").strip()
    if not order_id:
        return
    materialization_candidate = (
        postprocess_payload.get("materialization_candidate")
        if isinstance(postprocess_payload.get("materialization_candidate"), dict)
        else None
    )
    materialized_lines_payload = (
        postprocess_payload.get("materialized_lines_payload")
        if isinstance(postprocess_payload.get("materialized_lines_payload"), list)
        else None
    )
    confirmed_facility = str(postprocess_payload.get("confirmed_facility") or "").strip() or None
    confirmed_week = str(postprocess_payload.get("confirmed_week") or "").strip() or None

    logger.info("Order confirmed", order_id=order_id)
    record_event(
        "order_confirm",
        actor="system",
        target=order_id,
        fac=confirmed_facility,
        wek=confirmed_week,
    )
    _persist_confirmed_snapshot(
        order_id,
        confirmed_by="system",
        materialization_candidate=materialization_candidate,
        materialized_lines=materialized_lines_payload,
    )
    _invalidate_orders_cache()
    _invalidate_current_sheet_state_after_order_lines_write(order_id)
    try:
        _acknowledge_current_candidate_after_authoritative_action(
            order_id,
            selected_by="confirm-order",
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Workflow state refresh failed after confirm", order_id=order_id, error=str(exc))
    _register_training_sample_after_confirm(order_id)


def confirm_order_authoritatively(order_id: str) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    serialized_order: dict | None = None
    materialization_candidate: dict[str, Any] | None = None
    materialized_lines_payload: list[dict[str, Any]] | None = None
    confirmed_facility: str | None = None
    confirmed_week: str | None = None
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, None
        materialization_candidate = _build_confirm_materialization_candidate_from_draft(
            order_id,
            facility_id=order.facility_code,
            existing_week_code=order.week_code,
            received_at=order.received_at or datetime.utcnow(),
        )
        _materialize_confirmed_lines_from_candidate(session, order, materialization_candidate)
        session.flush()
        session.expire(order, ["lines"])
        materialized_lines_payload = _serialize_snapshot_lines(
            [
                dict(
                    id=line.id,
                    line_id=line.line_id,
                    date=line.date,
                    daypart=line.daypart,
                    menu_name=line.menu_name,
                    diet_type=line.diet_type,
                    area_id=line.area_id,
                    bag_type=line.bag_type,
                    quantity_original=line.quantity_original,
                    quantity_corrected=line.quantity_corrected,
                    change_note=line.change_note,
                )
                for line in (order.lines or [])
            ]
        )
        snapshot_payload = (
            _build_menu_snapshot_from_lines(
                facility_code=order.facility_code,
                week_code=order.week_code,
                lines=materialized_lines_payload,
            )
            if materialized_lines_payload
            else _build_menu_snapshot(order)
        )
        existing_snapshot = (
            session.execute(
                select(OrderMenuSnapshot).where(OrderMenuSnapshot.order_id == order_id)
            )
            .scalars()
            .first()
        )
        if existing_snapshot:
            existing_snapshot.snapshot_json = snapshot_payload
        else:
            session.add(
                OrderMenuSnapshot(
                    id=f"OMS{uuid4().hex[:8]}",
                    order_id=order_id,
                    snapshot_json=snapshot_payload,
                )
            )
        order.status = "確定"
        session.flush()
        session.refresh(order)
        confirmed_facility = order.facility_code
        confirmed_week = order.week_code
        serialized_order = serialize_order(order)
    if not isinstance(serialized_order, dict):
        return None, None
    return serialized_order, {
        "order_id": order_id,
        "materialization_candidate": materialization_candidate,
        "materialized_lines_payload": materialized_lines_payload,
        "confirmed_facility": confirmed_facility,
        "confirmed_week": confirmed_week,
    }


def confirm_order(order_id: str):
    serialized_order, postprocess_payload = confirm_order_authoritatively(order_id)
    if not isinstance(serialized_order, dict):
        return None
    finalize_confirmed_order(postprocess_payload)
    return serialized_order


def _resolve_order_current_week_selection(order: Order | dict[str, Any] | None) -> dict[str, Any]:
    if isinstance(order, dict):
        stored_week_value = (
            order.get("stored_week_value")
            or order.get("persisted_week_value")
            or order.get("week_code")
            or order.get("week_value")
            or order.get("week")
        )
        received_at = order.get("received_at")
        facility_id = order.get("facility")
    else:
        stored_week_value = getattr(order, "week_code", None)
        received_at = getattr(order, "received_at", None)
        facility_id = getattr(order, "facility_code", None)
    return week_candidate_service.resolve_current_week_selection(
        stored_week_value,
        received_at=received_at,
        facility_id=str(facility_id or "").strip() or None,
    )


def _resolve_order_current_sheet_week_value(order: Order | dict[str, Any] | None) -> str | None:
    selection = _resolve_order_current_week_selection(order)
    resolved_week_value = (
        str(selection.get("resolved_week_value") or "").strip()
        or str(selection.get("stored_week_value") or "").strip()
    )
    if resolved_week_value:
        return resolved_week_value
    if isinstance(order, dict):
        raw_week_value = (
            str(order.get("persisted_week_value") or "").strip()
            or str(order.get("week_value") or "").strip()
            or str(order.get("week") or "").strip()
        )
    else:
        raw_week_value = str(getattr(order, "week_code", None) or "").strip()
    return raw_week_value or None


def get_order_by_id(order_id: str):
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None
        payload = serialize_order(order)
        selection = _resolve_order_current_week_selection(order)
        stored_week_value = str(selection.get("stored_week_value") or "").strip() or None
        resolved_week_value = str(selection.get("resolved_week_value") or "").strip() or None
        resolved_week_label = str(selection.get("resolved_week_label") or "").strip() or None
        payload["stored_week_value"] = stored_week_value or payload.get("week_value")
        payload["persisted_week_value"] = resolved_week_value or payload.get("week_value")
        if resolved_week_value:
            payload["week_value"] = resolved_week_value
            payload["week_label"] = resolved_week_label or _format_sheet_week_label(resolved_week_value)
        return payload


def get_order_week_options(order_id: str) -> tuple[list[dict[str, Any]] | None, str | None]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        received_at = order.received_at or datetime.utcnow()
        facility_id = (order.facility_code or "").strip() or None
        current_week_selection = _resolve_order_current_week_selection(order)
        current_week_value = current_week_selection.get("stored_week_value")
        current_week_id = current_week_selection.get("month_id")
        selected_week_value = current_week_selection.get("resolved_week_value")
        if not (isinstance(selected_week_value, str) and "@" in selected_week_value):
            selected_week_value = None

    candidate_months: list[str] = []

    def _append(value: object) -> None:
        month_id = _to_sheet_month_id(value)
        if month_id and month_id not in candidate_months:
            candidate_months.append(month_id)

    anchor_month = _to_sheet_month_id(selected_week_value) or current_week_id or received_at.strftime("%Y-%m")

    for delta in (-2, -1, 0, 1, 2):
        _append(_shift_sheet_month_id(anchor_month, delta))

    options: list[dict[str, Any]] = []
    seen_week_values: set[str] = set()
    for month_id in candidate_months:
        for item in week_candidate_service.build_week_option_entries(month_id, facility_id):
            week_value = str(item.get("week_id") or "").strip()
            raw_start_date = str(item.get("date_from") or "").strip()
            raw_end_date = str(item.get("date_to") or "").strip()
            if not week_value or not raw_start_date or not raw_end_date:
                continue
            if week_value in seen_week_values:
                continue
            try:
                start_date = date.fromisoformat(raw_start_date)
                end_date = date.fromisoformat(raw_end_date)
            except Exception:
                continue
            selected = week_value == selected_week_value
            if not selected and not selected_week_value and start_date <= received_at.date() <= end_date:
                selected = True
            options.append(
                {
                    "week_id": week_value,
                    "label": str(item.get("label") or week_value),
                    "date_from": raw_start_date,
                    "date_to": raw_end_date,
                    "selected": selected,
                }
            )
            seen_week_values.add(week_value)
    if selected_week_value and not any(
        str(item.get("week_id") or "").strip() == selected_week_value for item in options
    ):
        selected_month_id, selected_week_start, selected_week_end = _parse_sheet_week_value(selected_week_value)
        if selected_month_id and isinstance(selected_week_start, date) and isinstance(selected_week_end, date):
            for item in options:
                item["selected"] = False
            options.insert(
                0,
                {
                    "week_id": selected_week_value,
                    "label": _format_sheet_week_label(selected_week_value),
                    "date_from": selected_week_start.isoformat(),
                    "date_to": selected_week_end.isoformat(),
                    "selected": True,
                },
            )
    return options, None


def _normalize_bag_summary_date(value: object) -> str:
    normalized = _normalize_entry_date(value)
    if isinstance(normalized, date):
        return normalized.isoformat()
    return str(value or "").strip()


def _bag_summary_group_key(
    *,
    date_value: object,
    daypart: object,
    menu_name: object,
    diet_type: object = None,
    area_id: object = None,
    bag_type: object = None,
) -> tuple[str, ...]:
    date_key = _normalize_bag_summary_date(date_value)
    daypart_key = _normalize_daypart_key(daypart)
    menu_key = _normalize_sheet_text(menu_name)
    bag_type_key = _normalize_sheet_text(bag_type).lower()
    if bag_type_key == "condiment":
        return ("condiment", date_key, daypart_key, menu_key)
    diet_key = _normalize_sheet_diet(diet_type) or _normalize_sheet_text(diet_type).lower()
    area_key = _normalize_sheet_area(area_id) or "X"
    return ("meal", date_key, daypart_key, menu_key, diet_key, area_key)


def _bag_summary_expected_totals(order_payload: dict[str, Any]) -> dict[tuple[str, ...], float]:
    from src.services.output_builder import build_order_lines_for_outputs

    totals: dict[tuple[str, ...], float] = {}
    order_lines = build_order_lines_for_outputs(order_payload)
    for line in order_lines:
        quantity_raw = (
            line.get("quantity_corrected")
            if line.get("quantity_corrected") is not None
            else line.get("quantity_original")
        )
        try:
            quantity = float(quantity_raw)
        except (TypeError, ValueError):
            continue
        if quantity <= 0:
            continue
        key = _bag_summary_group_key(
            date_value=line.get("date"),
            daypart=line.get("daypart"),
            menu_name=line.get("menu_name"),
            diet_type=line.get("diet_type"),
            area_id=line.get("area_id"),
            bag_type=line.get("bag_type"),
        )
        totals[key] = round(totals.get(key, 0.0) + quantity, 4)
    return totals


def _bag_summary_materialized_totals(rows: list[dict[str, Any]]) -> dict[tuple[str, ...], float]:
    totals: dict[tuple[str, ...], float] = {}
    for row in rows:
        try:
            quantity = float(row.get("quantity"))
        except (TypeError, ValueError):
            continue
        if quantity <= 0:
            continue
        key = _bag_summary_group_key(
            date_value=row.get("date"),
            daypart=row.get("daypart"),
            menu_name=row.get("menu_name"),
            diet_type=row.get("diet_type"),
            area_id=row.get("area_id"),
            bag_type=row.get("bag_type"),
        )
        totals[key] = round(totals.get(key, 0.0) + quantity, 4)
    return totals


def _bag_summary_requires_rebuild(
    order_payload: dict[str, Any],
    rows: list[dict[str, Any]],
) -> tuple[bool, str | None]:
    if not rows:
        return True, "missing_bags"
    expected_totals = _bag_summary_expected_totals(order_payload)
    materialized_totals = _bag_summary_materialized_totals(rows)
    if expected_totals != materialized_totals:
        return True, "bag_totals_mismatch"
    return False, None


def _normalize_output_unit(value: object) -> str:
    raw = str(value or "").strip()
    token = _normalize_sheet_text(value).lower()
    if not token:
        return ""
    if token in {"g", "gram", "grams"}:
        return "g"
    if token in {"ml"}:
        return "ml"
    if "個" in raw or token in {"count", "piece", "pieces"}:
        return "個"
    if "切" in raw or "枚" in raw or token in {"cut", "slice", "slices"}:
        return "切"
    return raw


def _format_amount_number(value: float) -> str:
    if float(value).is_integer():
        return str(int(value))
    return f"{value:.2f}".rstrip("0").rstrip(".")


def _format_amount_label(totals: dict[str, float] | None) -> str | None:
    if not isinstance(totals, dict):
        return None
    entries: list[tuple[str, float]] = []
    for unit, raw_value in totals.items():
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(value) or value < 0:
            continue
        entries.append((str(unit or ""), value))
    if not entries:
        return None
    entries.sort(key=lambda item: item[0])
    return " + ".join(f"{_format_amount_number(value)}{unit}" for unit, value in entries)


def _format_basis_label(per_serving: dict[str, float] | None) -> str | None:
    if not isinstance(per_serving, dict):
        return None
    entries: list[tuple[str, float]] = []
    for unit, raw_value in per_serving.items():
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(value) or value < 0:
            continue
        entries.append((str(unit or ""), value))
    if not entries:
        return None
    entries.sort(key=lambda item: item[0])
    return " + ".join(
        f"{_format_amount_number(value)}{unit}/人" if unit else f"{_format_amount_number(value)}/人"
        for unit, value in entries
    )


def _merge_amount_totals(base: dict[str, float], incoming: dict[str, float] | None) -> dict[str, float]:
    if not isinstance(incoming, dict):
        return base
    for unit, raw_value in incoming.items():
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(value) or value < 0:
            continue
        base[str(unit or "")] = round(base.get(str(unit or ""), 0.0) + value, 4)
    return base


def _build_condiment_amount_key(date_value: object, daypart: object) -> str:
    return f"condiment__{_normalize_bag_summary_date(date_value)}__{_normalize_daypart_key(daypart)}"


def _build_non_condiment_amount_key(
    date_value: object,
    daypart: object,
    menu_name: object,
    diet_type: object,
    area_id: object,
) -> str:
    return "__".join(
        [
            "normal",
            _normalize_bag_summary_date(date_value),
            _normalize_daypart_key(daypart),
            _normalize_sheet_text(menu_name),
            _normalize_sheet_diet(diet_type) or _normalize_sheet_text(diet_type).lower() or "unknown",
            _normalize_sheet_area(area_id) or "X",
        ]
    )


def _build_daily_bag_amount_stats(lines: list[dict[str, Any]]) -> dict[str, Any]:
    condiment_totals: dict[str, dict[str, float]] = {}
    non_condiment_stats: dict[str, dict[str, dict[str, float]]] = {}
    menu_category_by_group: dict[str, str] = {}
    for line in lines:
        quantity_raw = (
            line.get("quantity_corrected")
            if line.get("quantity_corrected") is not None
            else line.get("quantity_original")
        )
        try:
            quantity = float(quantity_raw)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(quantity) or quantity <= 0:
            continue
        unit = _normalize_output_unit(line.get("menu_unit_type") or line.get("actual_unit_type"))
        if not unit:
            continue
        amount_raw = None
        per_serving = line.get("menu_qty_per_serving")
        try:
            if per_serving is not None:
                per_serving_value = float(per_serving)
                if math.isfinite(per_serving_value) and per_serving_value >= 0:
                    amount_raw = per_serving_value * quantity
        except (TypeError, ValueError):
            amount_raw = None
        if amount_raw is None:
            amount_raw = line.get("actual_amount")
        try:
            amount = float(amount_raw)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(amount) or amount < 0:
            continue
        if _normalize_sheet_text(line.get("bag_type")).lower() == "condiment":
            key = _build_condiment_amount_key(line.get("date"), line.get("daypart"))
            totals = condiment_totals.get(key, {})
            totals[unit] = round(totals.get(unit, 0.0) + amount, 4)
            condiment_totals[key] = totals
            continue
        key = _build_non_condiment_amount_key(
            line.get("date"),
            line.get("daypart"),
            line.get("menu_name"),
            line.get("diet_type"),
            line.get("area_id"),
        )
        menu_category = str(line.get("menu_category") or "").strip()
        if menu_category and key not in menu_category_by_group:
            menu_category_by_group[key] = menu_category
        unit_stats = non_condiment_stats.get(key, {})
        current = unit_stats.get(unit, {"amount": 0.0, "quantity": 0.0})
        current["amount"] = round(current.get("amount", 0.0) + amount, 4)
        current["quantity"] = round(current.get("quantity", 0.0) + quantity, 4)
        unit_stats[unit] = current
        non_condiment_stats[key] = unit_stats
    per_serving_by_group: dict[str, dict[str, float]] = {}
    for key, unit_stats in non_condiment_stats.items():
        per_serving: dict[str, float] = {}
        for unit, stat in unit_stats.items():
            try:
                amount = float(stat.get("amount", 0.0))
                quantity = float(stat.get("quantity", 0.0))
            except (TypeError, ValueError):
                continue
            if not math.isfinite(amount) or not math.isfinite(quantity) or quantity <= 0:
                continue
            per_serving[unit] = round(amount / quantity, 6)
        if per_serving:
            per_serving_by_group[key] = per_serving
    return {
        "condiment_totals": condiment_totals,
        "per_serving_by_group": per_serving_by_group,
        "menu_category_by_group": menu_category_by_group,
    }


def _resolve_daily_bag_amount_totals(bag: dict[str, Any], stats: dict[str, Any]) -> dict[str, float] | None:
    bag_type = _normalize_sheet_text(bag.get("bag_type")).lower()
    if bag_type == "condiment":
        return stats.get("condiment_totals", {}).get(
            _build_condiment_amount_key(bag.get("date"), bag.get("daypart"))
        )
    try:
        quantity = float(bag.get("quantity"))
    except (TypeError, ValueError):
        return None
    if not math.isfinite(quantity) or quantity < 0:
        return None
    per_serving = stats.get("per_serving_by_group", {}).get(
        _build_non_condiment_amount_key(
            bag.get("date"),
            bag.get("daypart"),
            bag.get("menu_name"),
            bag.get("diet_type"),
            bag.get("area_id"),
        )
    )
    if not isinstance(per_serving, dict):
        return None
    totals: dict[str, float] = {}
    for unit, raw_value in per_serving.items():
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            continue
        if not math.isfinite(value) or value < 0:
            continue
        totals[unit] = round(value * quantity, 4)
    return totals or None


def _resolve_daily_bag_basis_label(bag: dict[str, Any], stats: dict[str, Any]) -> str | None:
    bag_type = _normalize_sheet_text(bag.get("bag_type")).lower()
    if bag_type == "condiment":
        return None
    per_serving = stats.get("per_serving_by_group", {}).get(
        _build_non_condiment_amount_key(
            bag.get("date"),
            bag.get("daypart"),
            bag.get("menu_name"),
            bag.get("diet_type"),
            bag.get("area_id"),
        )
    )
    return _format_basis_label(per_serving)


def _resolve_daily_bag_menu_category(bag: dict[str, Any], stats: dict[str, Any]) -> str | None:
    bag_type = _normalize_sheet_text(bag.get("bag_type")).lower()
    if bag_type == "condiment":
        return "付属品"
    return stats.get("menu_category_by_group", {}).get(
        _build_non_condiment_amount_key(
            bag.get("date"),
            bag.get("daypart"),
            bag.get("menu_name"),
            bag.get("diet_type"),
            bag.get("area_id"),
        )
    )


def _resolve_facility_label_for_code(facility_code: str) -> str:
    facility_code = str(facility_code or "").strip()
    if not facility_code:
        return "未確定"
    facility_name = ""
    try:
        facility_config = config_service.get_facility_config(facility_code) or {}
        facility_name = str(facility_config.get("facility_name") or "").strip()
    except Exception:
        facility_name = ""
    return f"{facility_name} ({facility_code})" if facility_name else facility_code


def _safe_per_serving_value(line: dict[str, Any]) -> float | None:
    raw = line.get("menu_qty_per_serving")
    if raw is None:
        quantity_raw = (
            line.get("quantity_corrected")
            if line.get("quantity_corrected") is not None
            else line.get("quantity_original")
        )
        amount_raw = line.get("actual_amount")
        try:
            quantity_value = float(quantity_raw)
            amount_value = float(amount_raw)
        except (TypeError, ValueError):
            return None
        if not math.isfinite(quantity_value) or quantity_value <= 0:
            return None
        if not math.isfinite(amount_value) or amount_value < 0:
            return None
        return round(amount_value / quantity_value, 6)
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(value) or value < 0:
        return None
    return round(value, 6)


def _safe_line_quantity_value(line: dict[str, Any]) -> float:
    raw = line.get("quantity_corrected")
    if raw is None:
        raw = line.get("quantity_original")
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return 0.0
    if not math.isfinite(value) or value < 0:
        return 0.0
    return value


def _build_daily_output_variant_basis_label(unit_type: str, qty_per_serving: float | None) -> str | None:
    if qty_per_serving is None:
        return None
    unit = _normalize_output_unit(unit_type)
    return _format_basis_label({unit: qty_per_serving} if unit else {"": qty_per_serving})


def list_daily_output_override_editor_rows(
    target_date: date,
    *,
    daypart: str,
    menu_name: str,
    menu_category: str | None = None,
) -> dict[str, Any]:
    normalized_daypart = daily_output_override_service.normalize_override_daypart(daypart)
    normalized_menu_name = daily_output_override_service.normalize_override_menu_name(menu_name)
    normalized_category = daily_output_override_service.normalize_override_category(menu_category)
    if not normalized_daypart or not normalized_menu_name:
        raise ValueError("daypart and menu_name are required")

    facility_labels: dict[str, str] = {}
    row_map: dict[tuple[str, str], dict[str, Any]] = {}
    overrides = daily_output_override_service.list_overrides(
        output_date=target_date,
        menu_name=menu_name,
        daypart=normalized_daypart,
        menu_category=normalized_category or None,
    )
    override_map = {
        (
            str(item.get("facility_id") or "").strip(),
            str(item.get("diet_type") or "").strip() or "unknown",
        ): item
        for item in overrides
    }
    orders = list_orders_by_line_date(target_date, facility_id=None, status=None)
    from src.services.output_builder import build_order_lines_for_outputs

    for order_summary in orders:
        order_id = str(order_summary.get("id") or "").strip()
        if not order_id:
            continue
        order_payload = get_order_by_id(order_id)
        if not isinstance(order_payload, dict):
            continue
        facility_code = str(order_payload.get("facility") or "").strip()
        facility_label = facility_labels.get(facility_code)
        if facility_label is None:
            facility_label = _resolve_facility_label_for_code(facility_code)
            facility_labels[facility_code] = facility_label
        lines = build_order_lines_for_outputs(order_payload)
        for line in lines:
            line_date = _normalize_entry_date(line.get("date"))
            if line_date != target_date:
                continue
            line_daypart = daily_output_override_service.normalize_override_daypart(line.get("daypart"))
            line_menu_name = daily_output_override_service.normalize_override_menu_name(line.get("menu_name"))
            line_category = daily_output_override_service.normalize_override_category(line.get("menu_category"))
            if line_daypart != normalized_daypart or line_menu_name != normalized_menu_name:
                continue
            if normalized_category and line_category != normalized_category:
                continue
            source_diet = daily_output_override_service.normalize_override_diet_type(line.get("diet_type")) or "unknown"
            row_key = (facility_code, source_diet)
            row = row_map.get(row_key)
            if row is None:
                row = {
                    "facility_id": facility_code,
                    "facility_label": facility_label,
                    "diet_type": source_diet,
                    "order_count": 0,
                    "total_quantity": 0.0,
                    "current_basis_label": None,
                    "current_qty_per_serving": None,
                    "current_unit_type": None,
                    "requires_intervention": False,
                    "current_variants": [],
                    "_variants": {},
                    "_order_ids": set(),
                    "override": None,
                }
                row_map[row_key] = row
            row["total_quantity"] += _safe_line_quantity_value(line)
            row["_order_ids"].add(order_id)
            per_serving_value = _safe_per_serving_value(line)
            unit_type = _normalize_output_unit(line.get("menu_unit_type") or line.get("actual_unit_type"))
            variant_key = (
                str(line.get("menu_name") or "").strip(),
                line_daypart,
                line_category,
                unit_type,
                per_serving_value,
            )
            variant = row["_variants"].get(variant_key)
            if variant is None:
                variant = {
                    "menu_name": str(line.get("menu_name") or "").strip(),
                    "daypart": line_daypart,
                    "menu_category": line_category,
                    "unit_type": unit_type,
                    "qty_per_serving": per_serving_value,
                    "basis_label": _build_daily_output_variant_basis_label(unit_type, per_serving_value),
                    "order_ids": set(),
                }
                row["_variants"][variant_key] = variant
            variant["order_ids"].add(order_id)

    rows: list[dict[str, Any]] = []
    for (facility_code, source_diet), row in row_map.items():
        variants = []
        for variant in row.pop("_variants").values():
            order_ids = sorted(list(variant.pop("order_ids")))
            variants.append({**variant, "order_ids": order_ids})
        variants.sort(
            key=lambda item: (
                item.get("menu_name") or "",
                item.get("unit_type") or "",
                item.get("qty_per_serving") or 0,
            )
        )
        row["current_variants"] = variants
        row["requires_intervention"] = len(variants) > 1
        row["order_count"] = len(row.pop("_order_ids"))
        row["total_quantity"] = round(float(row.get("total_quantity") or 0.0), 4)
        if len(variants) == 1:
            variant = variants[0]
            row["current_basis_label"] = variant.get("basis_label")
            row["current_qty_per_serving"] = variant.get("qty_per_serving")
            row["current_unit_type"] = variant.get("unit_type")
        existing_override = override_map.get((facility_code, source_diet))
        if existing_override:
            row["override"] = existing_override
        rows.append(row)

    rows.sort(key=lambda item: (item.get("facility_label") or "", item.get("diet_type") or ""))
    return {
        "date": target_date.isoformat(),
        "daypart": normalized_daypart,
        "menu_name": menu_name,
        "menu_category": normalized_category or "",
        "rows": rows,
    }


def _rebuild_bags_for_override_scope(target_date: date, facility_id: str) -> list[str]:
    return _rebuild_bags_for_override_scopes(target_date, [facility_id])


def _rebuild_bags_for_override_scopes(target_date: date, facility_ids: list[str]) -> list[str]:
    affected_order_ids: list[str] = []
    from src.services.output_builder import rebuild_bags

    seen_order_ids: set[str] = set()
    for facility_id in facility_ids:
        facility_code = str(facility_id or "").strip()
        if not facility_code:
            continue
        summaries = list_orders_by_line_date(target_date, facility_id=facility_code, status=None)
        for summary in summaries:
            order_id = str(summary.get("id") or "").strip()
            if not order_id or order_id in seen_order_ids:
                continue
            rebuild_bags(order_id)
            seen_order_ids.add(order_id)
            affected_order_ids.append(order_id)
    return affected_order_ids


def upsert_daily_output_portion_override(
    *,
    output_date: date,
    facility_id: str,
    menu_name: str,
    diet_type: str | None,
    daypart: str | None,
    menu_category: str | None,
    unit_type: str,
    qty_per_serving: float,
    note: str | None = None,
    updated_by: str | None = None,
    acknowledge_ambiguous: bool = False,
) -> dict[str, Any]:
    editor = list_daily_output_override_editor_rows(
        output_date,
        daypart=str(daypart or ""),
        menu_name=menu_name,
        menu_category=menu_category,
    )
    normalized_diet = daily_output_override_service.normalize_override_diet_type(diet_type) or "unknown"
    target_row = next(
        (
            row
            for row in editor.get("rows") or []
            if str(row.get("facility_id") or "").strip() == facility_id
            and str(row.get("diet_type") or "").strip() == normalized_diet
        ),
        None,
    )
    if target_row is None:
        raise ValueError(
            json.dumps(
                {
                    "code": "daily_output_override_target_not_found",
                    "facility_id": facility_id,
                    "diet_type": normalized_diet,
                },
                ensure_ascii=False,
            )
        )
    if target_row and target_row.get("requires_intervention") and not acknowledge_ambiguous:
        raise ValueError(
            json.dumps(
                {
                    "code": "daily_output_override_ambiguous",
                    "facility_id": facility_id,
                    "diet_type": normalized_diet,
                    "candidates": target_row.get("current_variants") or [],
                },
                ensure_ascii=False,
            )
        )
    override = daily_output_override_service.upsert_override(
        output_date=output_date,
        facility_id=facility_id,
        menu_name=menu_name,
        diet_type=normalized_diet,
        daypart=daypart,
        menu_category=menu_category,
        unit_type=unit_type,
        qty_per_serving=qty_per_serving,
        note=note,
        updated_by=updated_by,
    )
    affected_order_ids = _rebuild_bags_for_override_scope(output_date, facility_id)
    return {
        "override": override,
        "affected_order_ids": affected_order_ids,
    }


def upsert_daily_output_portion_override_bulk(
    *,
    output_date: date,
    menu_name: str,
    daypart: str | None,
    menu_category: str | None,
    unit_type: str,
    qty_per_serving: float,
    note: str | None = None,
    updated_by: str | None = None,
) -> dict[str, Any]:
    editor = list_daily_output_override_editor_rows(
        output_date,
        daypart=str(daypart or ""),
        menu_name=menu_name,
        menu_category=menu_category,
    )
    rows = list(editor.get("rows") or [])
    if not rows:
        raise ValueError(
            json.dumps(
                {
                    "code": "daily_output_override_target_not_found",
                    "menu_name": menu_name,
                    "daypart": str(daypart or ""),
                },
                ensure_ascii=False,
            )
        )
    blocking_rows = [
        {
            "facility_id": str(row.get("facility_id") or "").strip(),
            "facility_label": str(row.get("facility_label") or "").strip(),
            "diet_type": str(row.get("diet_type") or "").strip() or "unknown",
            "candidates": row.get("current_variants") or [],
        }
        for row in rows
        if row.get("requires_intervention")
    ]
    if blocking_rows:
        raise ValueError(
            json.dumps(
                {
                    "code": "daily_output_override_bulk_requires_intervention",
                    "rows": blocking_rows,
                },
                ensure_ascii=False,
            )
        )
    operations = [
        {
            "output_date": output_date,
            "facility_id": str(row.get("facility_id") or "").strip(),
            "menu_name": menu_name,
            "diet_type": row.get("diet_type"),
            "daypart": daypart,
            "menu_category": menu_category,
            "unit_type": unit_type,
            "qty_per_serving": qty_per_serving,
            "note": note,
            "updated_by": updated_by,
        }
        for row in rows
        if str(row.get("facility_id") or "").strip()
    ]
    overrides = daily_output_override_service.upsert_overrides(operations=operations)
    facility_ids = sorted({str(item.get("facility_id") or "").strip() for item in overrides if str(item.get("facility_id") or "").strip()})
    affected_order_ids = _rebuild_bags_for_override_scopes(output_date, facility_ids)
    return {
        "overrides": overrides,
        "affected_order_ids": affected_order_ids,
        "updated_count": len(overrides),
    }


def delete_daily_output_portion_override(override_id: str) -> dict[str, Any] | None:
    deleted = daily_output_override_service.delete_override(override_id)
    if not deleted:
        return None
    output_date = _normalize_entry_date(deleted.get("output_date"))
    facility_id = str(deleted.get("facility_id") or "").strip()
    affected_order_ids: list[str] = []
    if output_date and facility_id:
        affected_order_ids = _rebuild_bags_for_override_scope(output_date, facility_id)
    return {
        "override": deleted,
        "affected_order_ids": affected_order_ids,
    }


def get_daily_bag_summary(
    target_date: date,
    facility_id: Optional[str] = None,
    status: Optional[str] = None,
) -> dict[str, Any]:
    orders = list_orders_by_line_date(target_date, facility_id=facility_id, status=status)
    groups: dict[tuple[str, str], dict[str, Any]] = {}
    facility_labels: dict[str, str] = {}
    from src.services.output_builder import build_bag_payload_for_outputs, build_order_lines_for_outputs

    for order_summary in orders:
        order_id = str(order_summary.get("id") or "").strip()
        if not order_id:
            continue
        order_payload = get_order_by_id(order_id)
        if not isinstance(order_payload, dict):
            continue
        order_lines = build_order_lines_for_outputs(order_payload)
        amount_stats = _build_daily_bag_amount_stats(order_lines)
        bag_rows = build_bag_payload_for_outputs(order_payload, order_lines=order_lines)
        if not bag_rows:
            continue
        facility_code = str(order_payload.get("facility") or "").strip()
        facility_label = facility_labels.get(facility_code)
        if facility_label is None:
            facility_label = _resolve_facility_label_for_code(facility_code)
            facility_labels[facility_code] = facility_label

        for bag in bag_rows:
            if _normalize_bag_summary_date(bag.get("date")) != target_date.isoformat():
                continue
            group_daypart = str(bag.get("daypart") or _normalize_daypart_key(bag.get("daypart")) or "-").strip() or "-"
            menu_category = str(_resolve_daily_bag_menu_category(bag, amount_stats) or "-").strip() or "-"
            menu_name = str(bag.get("menu_name") or "-").strip() or "-"
            menu_key = (group_daypart, menu_category, menu_name)
            menu_group = groups.get(menu_key)
            if menu_group is None:
                menu_group = {
                    "daypart": group_daypart,
                    "daypart_key": _normalize_daypart_key(group_daypart),
                    "menu_category": menu_category,
                    "menu_name": menu_name,
                    "diet_groups": {},
                }
                groups[menu_key] = menu_group

            diet_key = bucket_diet_type_for_aggregation(bag.get("diet_type")) or "unknown"
            diet_group = menu_group["diet_groups"].get(diet_key)
            if diet_group is None:
                diet_group = {
                    "diet_type": diet_key,
                    "total_quantity": 0.0,
                    "total_amounts": {},
                    "calculation_basis_labels": set(),
                    "bag_type_groups": {},
                }
                menu_group["diet_groups"][diet_key] = diet_group

            try:
                quantity = float(bag.get("quantity"))
            except (TypeError, ValueError):
                quantity = 0.0
            if math.isfinite(quantity):
                diet_group["total_quantity"] = round(diet_group["total_quantity"] + quantity, 4)

            amount_totals = _resolve_daily_bag_amount_totals(bag, amount_stats)
            _merge_amount_totals(diet_group["total_amounts"], amount_totals)
            basis_label = _resolve_daily_bag_basis_label(bag, amount_stats)
            if basis_label:
                diet_group["calculation_basis_labels"].add(basis_label)

            bag_type_key = _normalize_sheet_text(bag.get("bag_type")).lower() or "standard"
            bag_type_group = diet_group["bag_type_groups"].get(bag_type_key)
            if bag_type_group is None:
                bag_type_group = {
                    "bag_type": bag_type_key,
                    "bag_count": 0,
                    "total_quantity": 0.0,
                    "total_amounts": {},
                    "breakdowns": {},
                }
                diet_group["bag_type_groups"][bag_type_key] = bag_type_group
            bag_type_group["bag_count"] += 1
            if math.isfinite(quantity):
                bag_type_group["total_quantity"] = round(bag_type_group["total_quantity"] + quantity, 4)
            _merge_amount_totals(bag_type_group["total_amounts"], amount_totals)

            amount_label = _format_amount_label(amount_totals) or "計算不可"
            breakdown = bag_type_group["breakdowns"].get(amount_label)
            if breakdown is None:
                breakdown = {
                    "amount_label": amount_label,
                    "count": 0,
                    "order_refs": [],
                }
                bag_type_group["breakdowns"][amount_label] = breakdown
            breakdown["count"] += 1
            breakdown["order_refs"].append(
                {
                    "order_id": order_id,
                    "facility_label": facility_label,
                    "area_id": bag.get("area_id"),
                    "quantity": quantity if math.isfinite(quantity) else None,
                }
            )

    preferred_diet_order = [
        "regular",
        "soft",
        "mixer",
        "forbidden",
        "tea",
        "business",
        "diabetes",
        "pregnancy",
        "sesame_allergy",
        "change_1",
        "change_2",
        "1600kcal",
        "placeholder",
        "unknown",
    ]
    diet_sort_index = {value: idx for idx, value in enumerate(preferred_diet_order)}
    bag_sort_order = {"large": 0, "medium": 1, "small": 2, "standard": 3, "condiment": 4}

    normalized_groups: list[dict[str, Any]] = []
    for menu_group in groups.values():
        diet_groups: list[dict[str, Any]] = []
        for diet_group in menu_group["diet_groups"].values():
            bag_type_groups: list[dict[str, Any]] = []
            for bag_type_group in diet_group["bag_type_groups"].values():
                breakdowns = list(bag_type_group["breakdowns"].values())
                breakdowns.sort(key=lambda item: (item.get("amount_label") == "計算不可", item.get("amount_label") or ""))
                bag_type_groups.append(
                    {
                        "bag_type": bag_type_group["bag_type"],
                        "bag_count": bag_type_group["bag_count"],
                        "total_quantity": bag_type_group["total_quantity"],
                        "total_amounts": bag_type_group["total_amounts"],
                        "total_amount_label": _format_amount_label(bag_type_group["total_amounts"]),
                        "breakdowns": breakdowns,
                    }
                )
            bag_type_groups.sort(
                key=lambda item: (
                    bag_sort_order.get(str(item.get("bag_type") or ""), 50),
                    str(item.get("bag_type") or ""),
                )
            )
            diet_groups.append(
                {
                    "diet_type": diet_group["diet_type"],
                    "total_quantity": diet_group["total_quantity"],
                    "total_amounts": diet_group["total_amounts"],
                    "total_amount_label": _format_amount_label(diet_group["total_amounts"]),
                    "calculation_basis_label": " / ".join(sorted(diet_group["calculation_basis_labels"]))
                    if diet_group["calculation_basis_labels"]
                    else None,
                    "bag_type_groups": bag_type_groups,
                }
            )
        diet_groups.sort(
            key=lambda item: (
                diet_sort_index.get(str(item.get("diet_type") or ""), 99),
                str(item.get("diet_type") or ""),
            )
        )
        normalized_groups.append(
            {
                "daypart": menu_group["daypart"],
                "daypart_key": menu_group["daypart_key"],
                "menu_category": menu_group["menu_category"],
                "menu_name": menu_group["menu_name"],
                "diet_groups": diet_groups,
            }
        )
    normalized_groups.sort(
        key=lambda item: (
            _daypart_sort_components(item.get("daypart"))[0],
            _daypart_sort_components(item.get("daypart"))[1],
            str(item.get("menu_category") or ""),
            str(item.get("menu_name") or ""),
        )
    )
    return {
        "date": target_date.isoformat(),
        "status": status,
        "facility_id": facility_id,
        "order_count": len(orders),
        "groups": normalized_groups,
    }


def get_bag_summary(order_id: str):
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return None, "order_not_found"
        bags = (
            session.execute(select(Bag).where(Bag.order_id == order_id))
            .scalars()
            .all()
        )
        payload = [
            {
                "id": bag.id,
                "date": bag.date.isoformat() if bag.date else None,
                "daypart": bag.daypart,
                "menu_name": bag.menu_name,
                "diet_type": bag.diet_type,
                "area_id": bag.area_id,
                "bag_type": bag.bag_type,
                "quantity": bag.quantity,
            }
            for bag in bags
        ]
    should_rebuild = False
    rebuild_reason: str | None = None
    order_payload = get_order_by_id(order_id)
    applied_overrides: list[dict[str, Any]] = []
    order_lines: list[dict[str, Any]] | None = None
    if isinstance(order_payload, dict):
        should_rebuild, rebuild_reason = _bag_summary_requires_rebuild(order_payload, payload)
        try:
            from src.services.output_builder import build_order_lines_for_outputs

            order_lines = build_order_lines_for_outputs(order_payload)
            applied_overrides = daily_output_override_service.collect_applied_override_summaries(order_lines)
        except Exception:
            applied_overrides = []
    elif not payload:
        should_rebuild = True
        rebuild_reason = "missing_bags"
    if should_rebuild:
        # Read paths should not materialize or rewrite Bag rows.
        # Serve a transient payload from current order lines instead.
        try:
            from src.services.output_builder import build_bag_payload_for_outputs, build_order_lines_for_outputs

            if isinstance(order_payload, dict):
                if order_lines is None:
                    order_lines = build_order_lines_for_outputs(order_payload)
                payload = build_bag_payload_for_outputs(order_payload, order_lines=order_lines)
            logger.info(
                "Bag summary served from transient lines",
                order_id=order_id,
                reason=rebuild_reason,
                bag_count=len(payload),
            )
        except Exception as exc:  # noqa: BLE001
            logger.warning(
                "Bag transient rebuild failed",
                order_id=order_id,
                reason=rebuild_reason,
                error=str(exc),
            )
    payload.sort(
        key=lambda row: (
            row.get("date") or "",
            row.get("daypart") or "",
            row.get("menu_name") or "",
            row.get("diet_type") or "",
            row.get("area_id") or "",
            row.get("bag_type") or "",
        )
    )
    return {
        "order_id": order_id,
        "generated": bool(payload),
        "bags": payload,
        "applied_portion_overrides": applied_overrides,
    }, None


def _load_cached_ocr(message_id: Optional[str]) -> Optional[dict]:
    if not message_id:
        return None
    candidates = []
    dump_dir = os.getenv("OCR_DEBUG_DUMP_DIR")
    if dump_dir:
        candidates.append(Path(dump_dir))
    candidates.append(Path(__file__).resolve().parents[1] / "tmp")
    for base in candidates:
        path = base / f"ocr_{message_id}.json"
        if path.exists():
            try:
                return json.loads(path.read_text(encoding="utf-8"))
            except Exception:  # noqa: BLE001
                return None
    return None


def _load_pipeline_raw_text(order_id: str, message_id: Optional[str]) -> Optional[str]:
    job = get_ocr_job(f"OCR-{order_id}")
    if not job and message_id:
        job = get_ocr_job(f"OCR-{message_id}")
    if not job:
        return None
    output_ref = job.get("output_reference")
    if not output_ref:
        return None
    try:
        payload = load_bytes_from_uri(output_ref)
        parsed = json.loads(payload.decode("utf-8"))
    except Exception:  # noqa: BLE001
        return None
    table_raw = parsed.get("table_raw")
    if isinstance(table_raw, str) and table_raw.strip():
        return table_raw
    try:
        return json.dumps(parsed, ensure_ascii=False, indent=2)
    except TypeError:
        return None


def _payload_has_hakodate_target_cells(payload: dict[str, Any]) -> bool:
    return bool(_extract_hakodate_target_cells_from_payload(payload))


def _payload_has_hakodate_evidence_records(payload: dict[str, Any], *, order_id: str) -> bool:
    return bool(_extract_hakodate_ocr_evidence_records_from_payload(payload, order_id=order_id))


def _payload_has_current_hakodate_canonical_pipeline(payload: dict[str, Any] | None) -> bool:
    if not isinstance(payload, dict):
        return False
    pipeline = payload.get("hakodate_canonical_pipeline")
    if not isinstance(pipeline, dict):
        return False
    version = str(pipeline.get("version") or "").strip()
    if version:
        return version == HAKODATE_CANONICAL_PIPELINE_VERSION
    # Compatibility for already-persisted Hakodate evidence created before the
    # canonical version field was added. This must still outrank order_ocr_cache;
    # otherwise a current evidence run can display a stale cached overlay.
    return (
        str(pipeline.get("producer") or "").strip()
        == "hakodate_cell_ocr_batch_service.build_hakodate_best_method_for_manifest_item"
        and str(pipeline.get("source") or "").strip() == "live_order_facility_source_workbook"
        and str(pipeline.get("requested_order_id") or "").strip() != ""
    )


def _hakodate_version_matches_current(value: object, *, allow_versionless: bool = False) -> bool:
    version = str(value or "").strip()
    if version == HAKODATE_CANONICAL_PIPELINE_VERSION:
        return True
    return allow_versionless and not version


def _payload_has_hakodate_output_content(payload: dict[str, Any] | None, *, order_id: str) -> bool:
    if not isinstance(payload, dict):
        return False
    if _payload_has_hakodate_target_cells(payload):
        return True
    if _payload_has_hakodate_evidence_records(payload, order_id=order_id):
        return True
    return isinstance(payload.get("hakodate_overlay"), dict)


def _grid_detection_payload(grid: object) -> dict[str, Any]:
    if isinstance(grid, dict):
        return grid
    return {
        "table_box": list(getattr(grid, "table_box", []) or []),
        "grid_column_edges": list(getattr(grid, "column_edges", []) or []),
        "grid_row_edges": list(getattr(grid, "row_edges", []) or []),
        "confidence": getattr(grid, "confidence", None),
    }


def _hakodate_week_rows_from_menu_entries(
    *,
    fields: list[str],
    week_id: str | None,
    facility_id: str | None,
) -> list[list[str]]:
    if not week_id:
        return []
    entries = _build_position_menu_entries_safe(week_id, facility_id)
    if not entries:
        return []
    date_idx = fields.index("date") if "date" in fields else fields.index("date_mmdd") if "date_mmdd" in fields else None
    daypart_idx = fields.index("daypart") if "daypart" in fields else None
    menu_idx = fields.index("menu_name") if "menu_name" in fields else fields.index("menu") if "menu" in fields else None
    if date_idx is None or daypart_idx is None or menu_idx is None:
        return []
    rows: list[list[str]] = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        row = ["" for _ in fields]
        menu_date = entry.get("menu_date")
        row[date_idx] = _format_mmdd(menu_date)
        row[daypart_idx] = str(entry.get("daypart_key") or entry.get("daypart") or "").strip()
        row[menu_idx] = str(entry.get("menu_name") or "").strip()
        if row[date_idx] and row[daypart_idx] and row[menu_idx]:
            rows.append(row)
    return rows


def _hakodate_target_cell_map_from_grid_and_rows(
    *,
    template: dict[str, Any],
    rows: list[list[str]],
    column_edges: list[float],
    row_edges: list[float],
    source: str,
) -> list[dict[str, Any]]:
    fields = _row_fields_from_template(template)
    if not fields or not rows:
        return []
    menu_idx = next(
        (
            idx
            for idx, field in enumerate(fields)
            if str(field or "").strip() in {"menu", "menu_name"}
        ),
        None,
    )
    if menu_idx is None or len(column_edges) < 2 or len(row_edges) < 2:
        return []
    header_rows = int(template.get("hakodate_header_rows") or max(0, len(row_edges) - 1 - len(rows)))
    header_rows = max(0, min(header_rows, max(0, len(row_edges) - 1)))
    date_idx = fields.index("date") if "date" in fields else fields.index("date_mmdd") if "date_mmdd" in fields else None
    daypart_idx = fields.index("daypart") if "daypart" in fields else None
    cells: list[dict[str, Any]] = []
    for payload_row_index, row in enumerate(rows):
        if not isinstance(row, list):
            continue
        grid_row = header_rows + payload_row_index
        if grid_row >= len(row_edges) - 1:
            break

        def _cell(index: int | None) -> str:
            if index is None or index >= len(row):
                return ""
            return str(row[index] or "").strip()

        date_value = _cell(date_idx)
        daypart = _cell(daypart_idx)
        menu_name = _cell(menu_idx)
        for col_index, field in enumerate(fields):
            semantic_field = str(field or "").strip()
            if col_index <= menu_idx or col_index >= len(column_edges) - 1:
                continue
            target_id = f"{source}-r{grid_row}c{col_index}"
            worksheet_row = grid_row + 1
            worksheet_col = col_index + 1
            sheet_cell = f"R{worksheet_row}C{worksheet_col}"
            cells.append(
                {
                    "target_cell_id": target_id,
                    "region_id": target_id,
                    "sheet_cell": sheet_cell,
                    "worksheet_row": worksheet_row,
                    "worksheet_col": worksheet_col,
                    "semantic_field": semantic_field,
                    "field_label": _field_label(semantic_field),
                    "date": date_value,
                    "daypart": daypart,
                    "menu_name": menu_name,
                    "bbox": [
                        column_edges[col_index],
                        row_edges[grid_row],
                        column_edges[col_index + 1],
                        row_edges[grid_row + 1],
                    ],
                    "center": [
                        (column_edges[col_index] + column_edges[col_index + 1]) / 2.0,
                        (row_edges[grid_row] + row_edges[grid_row + 1]) / 2.0,
                    ],
                    "logical_targets": [
                        {
                            "sheet_cell": sheet_cell,
                            "worksheet_row": worksheet_row,
                            "worksheet_col": worksheet_col,
                            "field": semantic_field,
                            "field_label": _field_label(semantic_field),
                            "date": date_value,
                            "daypart": daypart,
                            "menu_name": menu_name,
                        }
                    ],
                    "source": source,
                }
            )
    return cells


def _hakodate_document_context(order_id: str) -> dict[str, Any] | None:
    try:
        with session_scope() as session:
            order = session.get(Order, order_id)
            if not order:
                return None
            document_uri = str(order.document_uri or "").strip()
            if not document_uri:
                return None
            return {
                "document_uri": document_uri,
                "facility_id": str(order.facility_code or "").strip() or None,
                "week_id": str(order.week_code or "").strip() or None,
            }
    except Exception as exc:  # noqa: BLE001
        logger.warning("Hakodate document context lookup failed", order_id=order_id, error=str(exc))
        return None


def _hakodate_target_cell_map_from_order_document(
    *,
    order_id: str,
    template: dict[str, Any],
) -> list[dict[str, Any]]:
    context = _hakodate_document_context(order_id)
    if not isinstance(context, dict):
        return []
    fields = _row_fields_from_template(template)
    rows = _hakodate_week_rows_from_menu_entries(
        fields=fields,
        week_id=str(context.get("week_id") or "").strip() or None,
        facility_id=str(context.get("facility_id") or "").strip() or None,
    )
    if not rows:
        return []
    try:
        pdf_bytes = load_bytes_from_uri(str(context.get("document_uri") or ""))
        grid = detect_table_grid(
            pdf_bytes,
            {
                **template,
                "grid_auto_table_box": True,
                "grid_auto_use_raw_edges": True,
            },
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Hakodate target-cell grid generation failed", order_id=order_id, error=str(exc))
        return []
    grid_payload = _grid_detection_payload(grid)
    column_edges = [float(value) for value in (grid_payload.get("grid_column_edges") or grid_payload.get("column_edges") or [])]
    row_edges = [float(value) for value in (grid_payload.get("grid_row_edges") or grid_payload.get("row_edges") or [])]
    return _hakodate_target_cell_map_from_grid_and_rows(
        template=template,
        rows=rows,
        column_edges=column_edges,
        row_edges=row_edges,
        source="order_document_grid",
    )


