def _hakodate_best_method_draft_sheet(order_id: str) -> dict[str, Any] | None:
    base_sheet, error = _build_hakodate_weekly_menu_base_sheet(order_id)
    if error:
        logger.warning("Hakodate best method draft fallback failed", order_id=order_id, error=error)
    if not isinstance(base_sheet, dict):
        return None
    order = get_order_by_id(order_id)
    order_lines = order.get("lines") if isinstance(order, dict) and isinstance(order.get("lines"), list) else []
    if not order_lines:
        return base_sheet
    fields = [str(field or "").strip() for field in (base_sheet.get("fields") or [])]
    rows = [list(row) for row in (base_sheet.get("rows") or []) if isinstance(row, list)]
    quantity_index = _build_sheet_quantity_index(fields)
    if not fields or not rows or not quantity_index:
        return base_sheet
    date_idx = fields.index("date_mmdd") if "date_mmdd" in fields else (fields.index("date") if "date" in fields else -1)
    daypart_idx = fields.index("daypart") if "daypart" in fields else -1
    menu_idx = fields.index("menu") if "menu" in fields else (fields.index("menu_name") if "menu_name" in fields else -1)
    if date_idx < 0 or daypart_idx < 0 or menu_idx < 0:
        return base_sheet
    row_lookup: dict[tuple[str, str, str], int] = {}
    for row_index, row in enumerate(rows):
        key = _hakodate_sheet_identity(
            row[date_idx] if date_idx < len(row) else "",
            row[daypart_idx] if daypart_idx < len(row) else "",
            row[menu_idx] if menu_idx < len(row) else "",
        )
        if all(key) and key not in row_lookup:
            row_lookup[key] = row_index
    for line in order_lines:
        if not isinstance(line, dict):
            continue
        qty = line.get("quantity_corrected")
        if qty is None:
            qty = line.get("quantity_original")
        if qty is None:
            continue
        try:
            qty_float = float(qty)
        except Exception:
            continue
        col_idx = _resolve_quantity_column_index(
            quantity_index=quantity_index,
            diet_key=_normalize_sheet_diet(line.get("diet_type")),
            area_key=_normalize_sheet_area(line.get("area_id")),
        )
        if col_idx is None:
            continue
        row_index = row_lookup.get(_hakodate_sheet_identity(line.get("date"), line.get("daypart"), line.get("menu_name")))
        if row_index is None:
            continue
        while len(rows[row_index]) <= col_idx:
            rows[row_index].append("")
        rows[row_index][col_idx] = _numeric_string_add(str(rows[row_index][col_idx] or ""), qty_float)
    seeded = deepcopy(base_sheet)
    seeded["rows"] = rows
    seeded["source"] = "hakodate_confirmed_lines_seed_sheet"
    return seeded


def _estimate_hakodate_template_bbox_from_rendered_image(image: Any) -> list[float]:
    import cv2
    import numpy as np

    height, width = image.shape[:2]
    gray = cv2.cvtColor(image, cv2.COLOR_BGR2GRAY)
    binary = cv2.threshold(gray, 180, 255, cv2.THRESH_BINARY_INV)[1]
    horizontal = cv2.morphologyEx(
        binary,
        cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (80, 1)),
    )
    vertical = cv2.morphologyEx(
        binary,
        cv2.MORPH_OPEN,
        cv2.getStructuringElement(cv2.MORPH_RECT, (1, 80)),
    )
    combined = cv2.bitwise_or(horizontal, vertical)
    count, labels, stats, _centroids = cv2.connectedComponentsWithStats(combined, 8)
    best_bbox: list[float] | None = None
    best_score = 0.0
    for label in range(1, count):
        x, y, w, h, area = [int(value) for value in stats[label]]
        if w < width * 0.35 or h < height * 0.35:
            continue
        score = float(area) * float(w) * float(h)
        if score > best_score:
            best_score = score
            best_bbox = [float(x), float(y), float(x + w), float(y + h)]
    if best_bbox is None:
        raise ValueError("hakodate_template_bbox_not_found")
    return best_bbox


def _build_live_hakodate_manifest_item(
    *,
    order_id: str,
    facility_id: str,
    output_dir: Path,
    render_width: int = 1864,
) -> dict[str, Any]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            raise ValueError("order_not_found")
        document_uri = str(order.document_uri or "").strip()
        week_code = str(order.week_code or "").strip()
        workflow = session.get(OrderWorkflowState, order_id)
        workflow_meta = {}
        if workflow is not None and isinstance(workflow.secondary_actions_json, dict):
            raw_meta = workflow.secondary_actions_json.get("workflow_v2")
            workflow_meta = dict(raw_meta) if isinstance(raw_meta, dict) else {}
        selected_template_id = str(workflow_meta.get("template_id") or "").strip() or None
    if not document_uri:
        raise ValueError("document_missing")
    week_sheet_name = _week_sheet_name_from_week_value(week_code) or week_code
    if not week_sheet_name:
        raise ValueError("week_unresolved")

    structure_dir = output_dir / "_structure_template"
    structure_dir.mkdir(parents=True, exist_ok=True)
    fax_pdf_for_registration = document_uri
    parsed_document_uri = urlparse(document_uri)
    if parsed_document_uri.scheme in {"gs", "file"} or not Path(document_uri).exists():
        materialized_fax_pdf = structure_dir / f"{order_id}_fax.pdf"
        materialized_fax_pdf.write_bytes(load_bytes_from_uri(document_uri))
        fax_pdf_for_registration = str(materialized_fax_pdf)
    packaged_template_pdf = (
        Path(__file__).resolve().parents[2]
        / "tmp/outer_quad_eval_correct_20260426/preprocess_v10_template_snap_real_orders_20260425_0430/templates"
        / f"{facility_id}_{week_sheet_name}.pdf"
    )
    if packaged_template_pdf.exists():
        structure_pdf = packaged_template_pdf
    else:
        structure_xlsx = order_form_service.build_fax_structure_only_excel(
            facility_id=facility_id,
            week_sheet_name=week_sheet_name,
            output_dir=structure_dir,
        )
        structure_pdf = structure_dir / f"{structure_xlsx.stem}.pdf"
        render_workbook_path_to_pdf(
            structure_xlsx,
            output_path=structure_pdf,
            sheet_name=week_sheet_name,
        )
    from src.services.hakodate_fixed_quad_registration_service import (
        build_fixed_quad_template_registration,
        render_pdf_page_to_bgr,
    )

    # The accepted Hakodate runtime treats step2_png as the rectified FAX canvas,
    # not as the template image. Keep the runtime contract identical to the
    # locally accepted manifest by generating that rectified canvas here.
    accepted_canvas_width = 2362
    accepted_canvas_height = 4273
    template_image = render_pdf_page_to_bgr(str(structure_pdf), width=accepted_canvas_width)
    template_bbox = _estimate_hakodate_template_bbox_from_rendered_image(template_image)
    registration_dir = structure_dir / f"{facility_id}_{order_id}_fixed_quad"
    registration, _images = build_fixed_quad_template_registration(
        facility_code=facility_id,
        order_id=order_id,
        fax_pdf=fax_pdf_for_registration,
        template_pdf=str(structure_pdf),
        quad_px=None,
        manifest_template_bbox=template_bbox,
        canvas_width=accepted_canvas_width,
        canvas_height=accepted_canvas_height,
        render_width=render_width,
        quad_source=None,
        output_dir=registration_dir,
    )
    step2_png = Path(registration.outputs["step2"])
    return {
        "order_id": order_id,
        "facility_code": facility_id,
        "facility_id": facility_id,
        "fax_pdf": fax_pdf_for_registration,
        "template_pdf": str(structure_pdf),
        "fax_template_id": selected_template_id,
        "template_id": selected_template_id,
        "step2_png": str(step2_png),
        "template_bbox": template_bbox,
        "quad_px": registration.quad_px,
        "quad_source": registration.quad_source,
        "week_sheet_name": week_sheet_name,
        "source": "live_order_facility_source_workbook",
    }


def _hakodate_overlay_fingerprint(
    *,
    target_cells: list[dict[str, Any]],
    assignments: list[dict[str, Any]],
) -> str:
    return hashlib.sha256(
        json.dumps(
            {
                "target_cells": [
                    {
                        "target_cell_id": item.get("target_cell_id"),
                        "sheet_cell": item.get("sheet_cell"),
                        "bbox": item.get("bbox"),
                        "center": item.get("center"),
                    }
                    for item in target_cells
                    if isinstance(item, dict)
                ],
                "assignments": [
                    {
                        "target_cell_id": item.get("target_cell_id"),
                        "sheet_cell": item.get("sheet_cell"),
                        "assigned_value": item.get("assigned_value"),
                    }
                    for item in assignments
                    if isinstance(item, dict)
                ],
            },
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        ).encode("utf-8")
    ).hexdigest()


def _hakodate_canonical_payload_from_manifest_item(
    *,
    order_id: str,
    facility_id: str | None,
    item: dict[str, Any],
) -> dict[str, Any] | None:
    draft_sheet = _hakodate_best_method_draft_sheet(order_id)
    if not isinstance(draft_sheet, dict):
        raise ValueError("hakodate_best_method_draft_sheet_missing")
    with tempfile.TemporaryDirectory(prefix=f"hakodate_canonical_{order_id}_") as tmp:
        output_dir = Path(tmp)
        runtime_item = dict(item)
        if not all(str(runtime_item.get(key) or "").strip() for key in ("fax_pdf", "template_pdf", "step2_png")):
            if not facility_id:
                raise ValueError("facility_missing")
            runtime_item = _build_live_hakodate_manifest_item(
                order_id=order_id,
                facility_id=facility_id,
                output_dir=output_dir,
                render_width=1864,
            )
        result, _review_page = hakodate_cell_ocr_batch_service.build_hakodate_best_method_for_manifest_item(
            item=runtime_item,
            page=1,
            draft_sheet=draft_sheet,
            output_dir=output_dir,
            render_width=1864,
        )
        outputs = dict(result.outputs or {})
        regions_path = outputs.get("ocr_regions")
        records_path = outputs.get("records")
        overlay_path = outputs.get("overlay")
        if not regions_path:
            return None
        regions = json.loads(Path(regions_path).read_text(encoding="utf-8"))
        if not isinstance(regions, list):
            return None
        digit_records: list[dict[str, Any]] = []
        if records_path and Path(records_path).exists():
            loaded_records = json.loads(Path(records_path).read_text(encoding="utf-8"))
            if isinstance(loaded_records, list):
                digit_records = [item for item in loaded_records if isinstance(item, dict)]
        canonical_regions: list[dict[str, Any]] = []
        raw_evidence_records: list[dict[str, Any]] = []
        for index, region in enumerate(regions):
            if not isinstance(region, dict):
                continue
            copied = dict(region)
            copied["source"] = "hakodate_best_method_pipeline"
            canonical_regions.append(copied)
        evidence_source_records = digit_records or canonical_regions
        for index, region in enumerate(evidence_source_records):
            accepted_candidate = region.get("recognizer_accepted_candidate")
            accepted_candidate = accepted_candidate if isinstance(accepted_candidate, dict) else {}
            accepted_candidate_digits = str(accepted_candidate.get("normalized_digits") or "").strip()
            raw_text = str(
                accepted_candidate_digits
                or region.get("ocr_normalized")
                or region.get("ocr_text")
                or region.get("raw_text")
                or region.get("pred_digits")
                or ""
            ).strip()
            if not raw_text:
                continue
            confidence_source = (
                accepted_candidate.get("score")
                if str(region.get("recognizer_decision_source") or "").strip() == "topk_digits"
                else region.get("recognizer_score")
            )
            if confidence_source is None:
                confidence_source = region.get("score")
            try:
                confidence = float(confidence_source) if confidence_source is not None else None
            except Exception:
                confidence = None
            box = region.get("bbox")
            center = None
            if isinstance(box, list) and len(box) == 4:
                try:
                    center = [(float(box[0]) + float(box[2])) / 2.0, (float(box[1]) + float(box[3])) / 2.0]
                except Exception:
                    center = None
            raw_evidence_records.append(
                {
                    "text": raw_text,
                    "normalized_value": hakodate_ocr_evidence_service.normalize_ocr_value(raw_text),
                    "bbox": box,
                    "center": center,
                    "confidence": confidence,
                    "evidence_id": f"hakodate-cell-{index}",
                    "engine_metadata": {
                        "source_region_id": region.get("region_id"),
                        "sheet_cell": region.get("sheet_cell"),
                        "ocr_contact_slot_index": region.get("ocr_contact_slot_index"),
                        "source_artifact": "best_method_records" if digit_records else "best_method_ocr_regions",
                        "recognizer_score": region.get("recognizer_score"),
                        "recognizer_decision_source": region.get("recognizer_decision_source"),
                        "recognizer_accepted_candidate": accepted_candidate or None,
                    },
                }
            )
        target_cells = hakodate_ocr_evidence_service.target_cells_from_regions(canonical_regions)
        for cell in target_cells:
            cell["source"] = "hakodate_best_method_pipeline"
        evidence_records = hakodate_ocr_evidence_service.evidence_from_records(
            raw_evidence_records,
            run_id=f"{order_id}:hakodate-best-method",
            engine=str(result.ocr_engine or hakodate_cell_ocr_batch_service.DEFAULT_CELL_OCR_ENGINE),
            source_scope="hakodate_cell_crop_batch",
            raw_payload_ref=outputs.get("ocr_regions"),
        )
        canonical_blockers: list[str] = []
        if not target_cells:
            canonical_blockers.append("hakodate_target_cell_map_missing")
        if not evidence_records:
            canonical_blockers.append("hakodate_ocr_evidence_missing")
        assignment_result = (
            hakodate_ocr_evidence_service.assign_evidence_to_target_cells(
                evidence_records=evidence_records,
                target_cells=target_cells,
            )
            if target_cells and evidence_records
            else {
                "assignments": [],
                "blockers": [],
                "summary": {"assigned_target_count": 0},
            }
        )
        canonical_blockers.extend(
            str(item).strip()
            for item in (assignment_result.get("blockers") or [])
            if str(item).strip()
        )
        assigned_target_count = int((assignment_result.get("summary") or {}).get("assigned_target_count") or 0)
        if assigned_target_count <= 0:
            canonical_blockers.append("hakodate_assignment_missing")
        canonical_blockers = list(dict.fromkeys(item for item in canonical_blockers if item))
        overlay_fingerprint = _hakodate_overlay_fingerprint(
            target_cells=target_cells,
            assignments=[
                item
                for item in (assignment_result.get("assignments") or [])
                if isinstance(item, dict)
            ],
        )
        overlay_uri = None
        if overlay_path and Path(overlay_path).exists():
            bucket = get_default_output_bucket()
            if bucket:
                overlay_uri = save_artifact_bytes_to_gcs(
                    bucket,
                    f"OCR-{order_id}",
                    f"hakodate-overlay-{datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}-{uuid4().hex[:8]}.png",
                    Path(overlay_path).read_bytes(),
                    content_type="image/png",
                )
        return {
            "hakodate_preprocessing": {
                "target_cell_map": target_cells,
                "source": "hakodate_best_method_pipeline",
                "quality_gate": {
                    "ok": not canonical_blockers,
                    "target_cell_count": len(target_cells),
                    "evidence_record_count": len(evidence_records),
                    "assigned_target_count": assigned_target_count,
                    "blockers": canonical_blockers,
                },
            },
            "hakodate_ocr_evidence_records": evidence_records,
            "hakodate_overlay": {
                "uri": overlay_uri,
                "fingerprint": overlay_fingerprint,
                "producer": "hakodate_best_method_pipeline",
                "version": HAKODATE_CANONICAL_PIPELINE_VERSION,
                "generated_at": datetime.utcnow().isoformat(),
                "content_type": "image/png",
            }
            if overlay_uri
            else None,
            "hakodate_canonical_pipeline": {
                "producer": "hakodate_cell_ocr_batch_service.build_hakodate_best_method_for_manifest_item",
                "version": HAKODATE_CANONICAL_PIPELINE_VERSION,
                "status": "ready" if not canonical_blockers else "blocked",
                "blockers": canonical_blockers,
                "source": str(runtime_item.get("source") or "live_order_facility_source_workbook"),
                "manifest_path": None,
                "manifest_order_id": None,
                "manifest_facility_code": None,
                "requested_order_id": order_id,
                "requested_facility_id": facility_id,
                "draft_sheet_source": "latest_saved_draft",
                "week_sheet_name": runtime_item.get("week_sheet_name"),
                "template_bbox": runtime_item.get("template_bbox"),
                "target_cell_count": len(target_cells),
                "evidence_record_count": len(evidence_records),
                "assigned_target_count": assigned_target_count,
                "outputs": outputs,
            },
        }


def _augment_hakodate_ocr_payload_artifacts(
    *,
    order_id: str,
    payload: dict[str, Any],
    template: dict[str, Any] | None,
    force_hakodate: bool = False,
) -> dict[str, Any]:
    if not isinstance(template, dict):
        return payload
    if (
        not force_hakodate
        and hakodate_assignment_service.resolve_quantity_assignment_strategy(template) != "hakodate"
    ):
        return payload
    next_payload = dict(payload)
    if (
        not force_hakodate
        and _payload_has_current_hakodate_canonical_pipeline(next_payload)
        and _payload_has_hakodate_target_cells(next_payload)
        and _payload_has_hakodate_evidence_records(
            next_payload,
            order_id=order_id,
        )
    ):
        return next_payload
    context = _hakodate_document_context(order_id)
    facility_id = str((context or {}).get("facility_id") or "").strip() or None
    try:
        canonical_payload = _hakodate_canonical_payload_from_manifest_item(
            order_id=order_id,
            facility_id=facility_id,
            item={"source": "live_order_facility_source_workbook"},
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Hakodate canonical live pipeline failed", order_id=order_id, error=str(exc))
        next_payload["hakodate_canonical_pipeline"] = {
            "producer": "hakodate_cell_ocr_batch_service.build_hakodate_best_method_for_manifest_item",
            "status": "blocked",
            "blockers": ["hakodate_canonical_pipeline_failed"],
            "source": "live_order_facility_source_workbook",
            "manifest_path": None,
            "error": str(exc),
        }
        return next_payload
    if not isinstance(canonical_payload, dict):
        next_payload["hakodate_canonical_pipeline"] = {
            "producer": "hakodate_cell_ocr_batch_service.build_hakodate_best_method_for_manifest_item",
            "status": "blocked",
            "blockers": ["hakodate_canonical_pipeline_failed"],
            "source": "live_order_facility_source_workbook",
            "manifest_path": None,
        }
        return next_payload
    for key, value in canonical_payload.items():
        if value is not None:
            next_payload[key] = value
    return next_payload


def _preserve_hakodate_artifacts_if_missing(
    *,
    order_id: str,
    next_payload: dict[str, Any],
    existing_payload: dict[str, Any],
) -> dict[str, Any]:
    """Prevent lightweight read payloads from deleting reusable Hakodate artifacts."""
    if not isinstance(existing_payload, dict):
        return next_payload
    preserved = dict(next_payload)
    if preserved.get("hakodate_artifacts_reset_at"):
        return preserved
    if not _payload_has_hakodate_target_cells(preserved) and _payload_has_hakodate_target_cells(existing_payload):
        existing_preprocessing = existing_payload.get("hakodate_preprocessing")
        if isinstance(existing_preprocessing, dict):
            next_preprocessing = dict(preserved.get("hakodate_preprocessing") or {})
            for key in ("target_cell_map", "target_cells", "source", "quality_gate"):
                if key not in next_preprocessing and key in existing_preprocessing:
                    next_preprocessing[key] = deepcopy(existing_preprocessing[key])
            if next_preprocessing:
                preserved["hakodate_preprocessing"] = next_preprocessing
        for key in ("hakodate_target_cell_map",):
            if key not in preserved and key in existing_payload:
                preserved[key] = deepcopy(existing_payload[key])
    if (
        not _payload_has_hakodate_evidence_records(preserved, order_id=order_id)
        and _payload_has_hakodate_evidence_records(existing_payload, order_id=order_id)
    ):
        for key in ("hakodate_ocr_evidence", "hakodate_ocr_evidence_records"):
            if key not in preserved and key in existing_payload:
                preserved[key] = deepcopy(existing_payload[key])
    return preserved


def _save_order_ocr_cache(
    order_id: str,
    payload: dict,
    *,
    augment_hakodate_artifacts: bool = True,
    persist_evidence: bool = True,
    refresh_workflow: bool = True,
) -> None:
    next_payload = dict(payload) if isinstance(payload, dict) else {}
    template = _resolve_order_fax_template(order_id)
    annotated_payload = _annotate_payload_with_template_field_schema(next_payload, template)
    if isinstance(annotated_payload, dict):
        next_payload = annotated_payload
    if augment_hakodate_artifacts:
        next_payload = _augment_hakodate_ocr_payload_artifacts(
            order_id=order_id,
            payload=next_payload,
            template=template,
        )
    try:
        with session_scope() as session:
            cache = session.get(OrderOcrCache, order_id)
            if not cache:
                cache = OrderOcrCache(order_id=order_id)
                session.add(cache)
            existing_payload = cache.payload if isinstance(cache.payload, dict) else {}
            if (
                isinstance(existing_payload, dict)
                and _payload_has_page_artifacts(existing_payload)
                and not _payload_has_page_artifacts(next_payload)
            ):
                for preserved_key in ("pages", "combined", "engine", "template_id", "facility_id"):
                    preserved_value = existing_payload.get(preserved_key)
                    if preserved_key not in next_payload and preserved_value is not None:
                        next_payload[preserved_key] = preserved_value
            for preserved_key in ("_edited_ocr", "_reparse_debug"):
                preserved_value = existing_payload.get(preserved_key)
                if isinstance(preserved_value, dict) and preserved_key not in next_payload:
                    next_payload[preserved_key] = preserved_value
            next_payload = _preserve_hakodate_artifacts_if_missing(
                order_id=order_id,
                next_payload=next_payload,
                existing_payload=existing_payload,
            )
            cache.payload = next_payload
            cache.updated_at = datetime.utcnow()
    except Exception as exc:  # noqa: BLE001
        logger.warning("Order OCR cache save failed", order_id=order_id, error=str(exc))
    if persist_evidence and _payload_has_hakodate_output_content(next_payload, order_id=order_id):
        persist_evidence = False
    if persist_evidence:
        try:
            persist_ocr_evidence_run(
                order_id,
                next_payload,
                schema_version="v1_legacy",
                producer_version="legacy-cache-mirror/v1",
                status=str(next_payload.get("status") or "ready").strip() or "ready",
                refresh_workflow=False,
            )
        except Exception as exc:  # noqa: BLE001
            logger.warning("Order OCR evidence persistence failed", order_id=order_id, error=str(exc))
    if refresh_workflow:
        try:
            workflow_state_service.refresh_workflow_state(order_id)
        except Exception as exc:  # noqa: BLE001
            logger.warning("Workflow state refresh failed after OCR cache save", order_id=order_id, error=str(exc))


def _load_order_ocr_cache(order_id: str) -> Optional[dict]:
    try:
        with session_scope() as session:
            cache = session.get(OrderOcrCache, order_id)
            if not cache:
                return None
            return cache.payload if isinstance(cache.payload, dict) else None
    except Exception as exc:  # noqa: BLE001
        logger.warning("Order OCR cache load failed", order_id=order_id, error=str(exc))
        return None


def get_cached_ocr_payload(order_id: str) -> Optional[dict]:
    return evidence_manifest_service.ensure_evidence_manifest(_load_order_ocr_cache(order_id))


def persist_ocr_evidence_run(
    order_id: str,
    payload: dict[str, Any] | None,
    *,
    schema_version: str = "v1_legacy",
    producer_version: str | None = None,
    status: str = "ready",
    source: str | None = None,
    refresh_workflow: bool = True,
) -> Optional[dict]:
    prepared_payload = dict(payload) if isinstance(payload, dict) else payload
    template = _resolve_order_fax_template(order_id)
    if isinstance(prepared_payload, dict):
        annotated_payload = _annotate_payload_with_template_field_schema(prepared_payload, template)
        if isinstance(annotated_payload, dict):
            prepared_payload = annotated_payload
    persisted = ocr_evidence_service.persist_evidence_run(
        order_id=order_id,
        payload=prepared_payload,
        schema_version=schema_version,
        producer_version=producer_version,
        status=status,
        source=source,
    )
    if persisted is not None and refresh_workflow:
        try:
            workflow_state_service.refresh_workflow_state(order_id)
        except Exception as exc:  # noqa: BLE001
            logger.warning("Workflow state refresh failed after evidence persist", order_id=order_id, error=str(exc))
    return persisted


def get_latest_ocr_evidence_run(order_id: str, *, backfill_from_cache: bool = True) -> Optional[dict]:
    latest = ocr_evidence_service.get_latest_evidence_run(order_id)
    if latest is not None or not backfill_from_cache:
        return latest
    # Backfill must not depend on active-evidence resolution because the active
    # path itself resolves through latest evidence state.
    cached_payload = _load_order_ocr_cache(order_id)
    if not isinstance(cached_payload, dict):
        return None
    cached_payload = _restore_payload_raw_ocr_surface(
        cached_payload,
        strip_legacy_surface=True,
    )
    return ocr_evidence_service.backfill_evidence_run_from_cached_payload(
        order_id,
        cached_payload,
        schema_version="v1_legacy_backfill",
        producer_version="legacy-cache-backfill/v1",
        source="legacy-cache-backfill",
    )


def _resolve_active_ocr_evidence_run(order_id: str) -> Optional[dict]:
    latest_evidence = get_latest_ocr_evidence_run(order_id, backfill_from_cache=True)
    latest_draft = draft_sheet_service.get_latest_sheet_draft(order_id)
    if not _draft_record_is_authoritative_current_sheet(latest_draft):
        latest_draft = None
    resolved = workflow_state_service._resolve_active_evidence_run(latest_evidence, latest_draft)
    return resolved if isinstance(resolved, dict) else None


def _load_active_ocr_payload(order_id: str) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    active_evidence = _resolve_active_ocr_evidence_run(order_id)
    payload = active_evidence.get("payload_json") if isinstance(active_evidence, dict) else None
    if not isinstance(payload, dict):
        return None, active_evidence
    template = _resolve_order_fax_template(order_id)
    cached_payload = _load_order_ocr_cache(order_id)
    prepared_payload = evidence_manifest_service.ensure_evidence_manifest(dict(payload))
    prepared_payload = _merge_legacy_first_pass_payload(
        prepared_payload,
        active_evidence,
        cached_payload if isinstance(cached_payload, dict) else None,
        template=template,
    )
    prepared_payload = _restore_payload_raw_ocr_surface(
        prepared_payload,
        strip_legacy_surface=True,
    )
    prepared_payload = _annotate_payload_with_template_field_schema(prepared_payload, template)
    prepared_payload = _augment_payload_with_candidate_resolution(order_id, prepared_payload)
    if not isinstance(prepared_payload, dict):
        return None, active_evidence
    return evidence_manifest_service.ensure_evidence_manifest(dict(prepared_payload)), active_evidence


def get_ocr_evidence_run(evidence_run_id: str) -> Optional[dict]:
    return ocr_evidence_service.get_evidence_run(evidence_run_id)


def persist_sheet_draft(
    *,
    order_id: str,
    draft_sheet_json: dict[str, Any] | None,
    draft_state: str = "draft_ready",
    blockers: list[str] | None = None,
    warnings: list[str] | None = None,
    latest_patch_candidate_id: str | None = None,
    edited_by: str | None = None,
) -> Optional[dict]:
    if not isinstance(draft_sheet_json, dict):
        return None
    latest_evidence = get_latest_ocr_evidence_run(order_id, backfill_from_cache=True)
    template_resolution_id = None
    if isinstance(latest_evidence, dict):
        payload_json = latest_evidence.get("payload_json")
        if isinstance(payload_json, dict):
            resolution = payload_json.get("template_resolution")
            if isinstance(resolution, dict):
                template_resolution_id = (
                    str(resolution.get("resolved_template_id") or resolution.get("template_id") or "").strip() or None
                )
    persisted = draft_sheet_service.persist_sheet_draft(
        order_id=order_id,
        draft_sheet_json=draft_sheet_json,
        base_evidence_run_id=(latest_evidence or {}).get("id") if isinstance(latest_evidence, dict) else None,
        base_template_resolution_id=template_resolution_id,
        draft_state=draft_state,
        blockers=blockers,
        warnings=warnings,
        latest_patch_candidate_id=latest_patch_candidate_id,
        edited_by=edited_by,
    )
    if persisted is not None:
        try:
            workflow_state_service.refresh_workflow_state(
                order_id,
                refresh_draft_from_semantic=False,
            )
        except Exception as exc:  # noqa: BLE001
            logger.warning("Workflow state refresh failed after draft persist", order_id=order_id, error=str(exc))
    return persisted


def _dedupe_str_tokens(values: list[object] | None) -> list[str]:
    deduped: list[str] = []
    seen: set[str] = set()
    for value in values or []:
        token = str(value or "").strip()
        if token and token not in seen:
            seen.add(token)
            deduped.append(token)
    return deduped


def _slice_monthly_menu_entries_for_week(
    entries: object,
    *,
    week_start: date | None,
    week_end: date | None,
) -> list[dict[str, Any]]:
    normalized_entries = [item for item in (entries or []) if isinstance(item, dict)]
    if not isinstance(week_start, date) or not isinstance(week_end, date):
        return normalized_entries
    sliced: list[dict[str, Any]] = []
    for item in normalized_entries:
        menu_date = _parse_date_value(item.get("menu_date"))
        if isinstance(menu_date, date) and week_start <= menu_date <= week_end:
            sliced.append(item)
    return sliced


def _build_monthly_menu_diagnostics(
    *,
    week_id: str | None,
    facility_id: str | None,
) -> dict[str, Any]:
    normalized_week_id = str(week_id or "").strip() or None
    month_id, week_start, week_end = _parse_sheet_week_value(normalized_week_id)
    diagnostics: dict[str, Any] = {
        "month_id": month_id,
        "resolved_week_id": normalized_week_id,
        "order_codes": [],
        "row_codes": [],
        "global_entries_count": 0,
        "facility_entries_count": 0,
    }
    if not month_id:
        return diagnostics
    target_month_ids = _sheet_week_month_ids(normalized_week_id) or ([month_id] if month_id else [])
    try:
        global_menus: dict[str, dict[str, Any]] = {}
        facility_menus: dict[str, dict[str, Any]] = {}
        for target_month_id in target_month_ids:
            global_payload = menu_service.get_menu(target_month_id)
            if isinstance(global_payload, dict):
                global_menus[target_month_id] = global_payload
            facility_payload = (
                menu_service.get_menu_for_facility(target_month_id, facility_id)
                if str(facility_id or "").strip()
                else global_payload
            )
            if isinstance(facility_payload, dict):
                facility_menus[target_month_id] = facility_payload
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "Monthly menu diagnostics lookup failed",
            month_id=month_id,
            week_id=normalized_week_id,
            facility_id=facility_id,
            error=str(exc),
        )
        diagnostics["order_codes"] = ["monthly_menu_lookup_failed"]
        return diagnostics
    if len(global_menus) != len(target_month_ids):
        diagnostics["order_codes"] = ["monthly_menu_object_missing"]
        return diagnostics

    global_entries: list[dict[str, Any]] = []
    for target_month_id in target_month_ids:
        global_entries.extend(
            _slice_monthly_menu_entries_for_week(
                global_menus.get(target_month_id, {}).get("entries"),
                week_start=week_start,
                week_end=week_end,
            )
        )
    diagnostics["global_entries_count"] = len(global_entries)
    if not global_entries:
        diagnostics["order_codes"] = ["menu_entries_missing"]
        return diagnostics

    facility_entries: list[dict[str, Any]] = []
    for target_month_id in target_month_ids:
        facility_entries.extend(
            _slice_monthly_menu_entries_for_week(
                facility_menus.get(target_month_id, {}).get("entries") if isinstance(facility_menus.get(target_month_id), dict) else [],
                week_start=week_start,
                week_end=week_end,
            )
        )
    diagnostics["facility_entries_count"] = len(facility_entries)
    if str(facility_id or "").strip() and (len(facility_menus) != len(target_month_ids) or not facility_entries):
        diagnostics["order_codes"] = ["monthly_menu_facility_scope_missing"]
    return diagnostics


_MENU_DIAGNOSTIC_CANONICAL_PRIORITY: tuple[str, ...] = (
    "monthly_menu_object_missing",
    "monthly_menu_facility_scope_missing",
    "monthly_menu_lookup_failed",
    "menu_entries_missing",
)


def _canonical_menu_diagnostic_code(
    diagnostics: dict[str, Any] | None,
    *,
    fallback_code: str | None = None,
) -> str | None:
    codes = [
        str(item).strip()
        for item in ((diagnostics or {}).get("order_codes") or [])
        if str(item or "").strip()
    ]
    for candidate in _MENU_DIAGNOSTIC_CANONICAL_PRIORITY:
        if candidate in codes:
            return candidate
    normalized_fallback = str(fallback_code or "").strip()
    if normalized_fallback in _MENU_DIAGNOSTIC_CANONICAL_PRIORITY:
        return normalized_fallback
    return None


def _replace_menu_blocker_tokens(
    tokens: list[str] | None,
    *,
    canonical_code: str | None,
) -> list[str]:
    normalized = [
        str(item).strip()
        for item in (tokens or [])
        if str(item or "").strip()
        and str(item).strip() not in _MENU_DIAGNOSTIC_CANONICAL_PRIORITY
    ]
    if canonical_code and canonical_code not in normalized:
        normalized.append(canonical_code)
    return normalized


def _split_sheet_source(source: object) -> tuple[str | None, str | None]:
    normalized = str(source or "").strip()
    if not normalized:
        return None, None
    if "+" not in normalized:
        return normalized, None
    seed_source, enrichment_source = [item.strip() or None for item in normalized.split("+", 1)]
    return seed_source, enrichment_source


def _draft_fields_look_generic(fields: object) -> bool:
    if not isinstance(fields, list) or not fields:
        return False
    normalized = [str(field or "").strip() for field in fields if str(field or "").strip()]
    if not normalized:
        return False
    return all(re.fullmatch(r"col\d+", token) for token in normalized)


def _sheet_row_identity_key(fields: list[str], row: list[Any]) -> tuple[str, str, str] | None:
    if not isinstance(fields, list) or not isinstance(row, list):
        return None
    try:
        date_idx = fields.index("date_mmdd")
        daypart_idx = fields.index("daypart")
        menu_idx = fields.index("menu")
    except ValueError:
        return None
    parts = []
    for idx in (date_idx, daypart_idx, menu_idx):
        if idx >= len(row):
            return None
        token = str(row[idx] or "").strip()
        if not token:
            return None
        parts.append(token)
    return tuple(parts)


def _sheet_cell_has_value(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return value.strip() != ""
    return True


def _merge_saved_draft_into_semantic_sheet(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
    *,
    append_unmatched_current_rows: bool = True,
    merge_current_warnings: bool = True,
    preserve_blank_quantity_values: bool = True,
    preserve_current_quantity_values: bool = True,
) -> dict[str, Any] | None:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        return fresh_sheet if isinstance(fresh_sheet, dict) else current_sheet
    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    fresh_rows = [list(row) for row in (fresh_sheet.get("rows") or []) if isinstance(row, list)]
    if not current_fields or not fresh_fields or not fresh_rows:
        return fresh_sheet

    current_rows = _sanitize_semantic_sheet_rows(
        rows_payload=current_sheet.get("rows"),
        fields=current_fields,
    )
    current_row_ids = [str(item).strip() for item in (current_sheet.get("row_ids") or []) if str(item).strip()]
    fresh_row_ids = [str(item).strip() for item in (fresh_sheet.get("row_ids") or []) if str(item).strip()]
    if len(fresh_row_ids) < len(fresh_rows):
        fresh_row_ids.extend([f"row-{idx + 1}" for idx in range(len(fresh_row_ids), len(fresh_rows))])

    current_index = {field: idx for idx, field in enumerate(current_fields)}
    fresh_index = {field: idx for idx, field in enumerate(fresh_fields)}
    authoritative_shell = (
        _fresh_sheet_has_authoritative_weekly_shell(fresh_sheet)
        and _fields_compatible_for_authoritative_weekly_shell_rebase(current_fields, fresh_fields)
    )
    shell_fields = {"date_mmdd", "daypart", "menu"} if authoritative_shell else set()
    current_quantity_fields = [field for field in current_fields if field.startswith("qty.")]
    fresh_quantity_fields = [field for field in fresh_fields if field.startswith("qty.")]
    shared_quantity_fields = [
        field
        for field in current_quantity_fields
        if field.startswith("qty.") and field in fresh_index
    ]
    current_by_key: dict[tuple[str, str, str], tuple[list[Any], str | None]] = {}
    unmatched_current: list[tuple[list[Any], str | None]] = []
    for idx, row in enumerate(current_rows):
        row_key = _sheet_row_identity_key(current_fields, row)
        row_id = current_row_ids[idx] if idx < len(current_row_ids) else None
        if row_key is None:
            unmatched_current.append((row, row_id))
            continue
        current_by_key[row_key] = (row, row_id)

    merged_rows: list[list[Any]] = []
    merged_row_ids: list[str] = []
    matched_keys: set[tuple[str, str, str]] = set()
    for idx, fresh_row in enumerate(fresh_rows):
        row_key = _sheet_row_identity_key(fresh_fields, fresh_row)
        merged_row = list(fresh_row)
        merged_row_id = fresh_row_ids[idx] if idx < len(fresh_row_ids) else f"row-{idx + 1}"
        if row_key is not None and row_key in current_by_key:
            current_row, current_row_id = current_by_key[row_key]
            matched_keys.add(row_key)
            for field_name in fresh_quantity_fields:
                if field_name in shared_quantity_fields:
                    continue
                fresh_idx = fresh_index[field_name]
                while len(merged_row) <= fresh_idx:
                    merged_row.append("")
                merged_row[fresh_idx] = ""
            for field_name, current_idx in current_index.items():
                fresh_idx = fresh_index.get(field_name)
                if fresh_idx is None or current_idx >= len(current_row):
                    continue
                current_value = current_row[current_idx]
                if field_name.startswith("qty."):
                    if preserve_current_quantity_values and (
                        _sheet_cell_has_value(current_value)
                        and (
                            preserve_blank_quantity_values
                            or not _sheet_cell_has_value(merged_row[fresh_idx])
                        )
                    ):
                        merged_row[fresh_idx] = current_value
                elif _is_aux_sheet_field(field_name):
                    continue
                elif field_name in shell_fields:
                    continue
                elif str(current_value or "").strip() != "":
                    merged_row[fresh_idx] = current_value
            if current_row_id:
                merged_row_id = current_row_id
        merged_rows.append(merged_row)
        merged_row_ids.append(merged_row_id)

    non_shell_fields = [
        field
        for field in current_fields
        if field not in shell_fields and not field.startswith("qty.")
    ]

    def _should_append_unmatched_current_row(row: list[Any]) -> bool:
        if not authoritative_shell:
            return True
        for field_name in non_shell_fields:
            field_idx = current_index.get(field_name)
            if field_idx is None or field_idx >= len(row):
                continue
            if str(row[field_idx] or "").strip():
                return True
        return False

    if append_unmatched_current_rows:
        for row_key, (current_row, current_row_id) in current_by_key.items():
            if row_key in matched_keys:
                continue
            if not _should_append_unmatched_current_row(current_row):
                continue
            appended = [""] * len(fresh_fields)
            for field_name, current_idx in current_index.items():
                fresh_idx = fresh_index.get(field_name)
                if fresh_idx is None or current_idx >= len(current_row):
                    continue
                appended[fresh_idx] = current_row[current_idx]
            merged_rows.append(appended)
            merged_row_ids.append(current_row_id or f"row-{len(merged_row_ids) + 1}")

        for current_row, current_row_id in unmatched_current:
            if not _should_append_unmatched_current_row(current_row):
                continue
            appended = [""] * len(fresh_fields)
            for field_name, current_idx in current_index.items():
                fresh_idx = fresh_index.get(field_name)
                if fresh_idx is None or current_idx >= len(current_row):
                    continue
                appended[fresh_idx] = current_row[current_idx]
            if any(str(cell or "").strip() for cell in appended):
                merged_rows.append(appended)
                merged_row_ids.append(current_row_id or f"row-{len(merged_row_ids) + 1}")

    merged_warnings: list[str] = []
    warning_sources: list[Any] = []
    if merge_current_warnings:
        warning_sources.extend(list(current_sheet.get("warnings") or []))
    warning_sources.extend(list(fresh_sheet.get("warnings") or []))
    for warning in warning_sources:
        token = str(warning or "").strip()
        if token and token not in merged_warnings:
            merged_warnings.append(token)

    merged = dict(fresh_sheet)
    merged["rows"] = merged_rows
    merged["row_ids"] = merged_row_ids
    merged["warnings"] = merged_warnings
    ui_mode = str(current_sheet.get("ui_mode") or fresh_sheet.get("ui_mode") or "").strip()
    if ui_mode:
        merged["ui_mode"] = ui_mode
    return merged


_SEMANTIC_REFRESH_PRUNE_BLOCKERS = {
    "week_unresolved",
    "menu_entries_missing",
    "sheet_fields_not_found",
    "sheet_fields_duplicate",
    "sheet_template_field_invalid",
    "sheet_quantity_columns_missing",
    "sheet_quantity_column_unmapped",
    "sheet_week_dates_incomplete",
    "week_menu_date_mismatch",
    "sheet_date_mismatch",
    "sheet_canonical_mismatch",
    "sheet_suspicious_blank_row",
    "ocr_evidence_recovery_required",
    "template_resolution_blocked",
    "template_unresolved",
    "auto_apply_blocked",
}


def _fresh_sheet_has_authoritative_weekly_shell(sheet: dict[str, Any] | None) -> bool:
    if not isinstance(sheet, dict):
        return False
    if not _source_uses_weekly_menu_shell(sheet.get("source")):
        return False
    fields = [str(field).strip() for field in (sheet.get("fields") or []) if str(field).strip()]
    rows = _sanitize_semantic_sheet_rows(
        rows_payload=sheet.get("rows"),
        fields=fields,
    )
    required = ["date_mmdd", "daypart", "menu"]
    index = {field: idx for idx, field in enumerate(fields)}
    if any(field not in index for field in required):
        return False
    if not rows:
        return False
    last_required_idx = max(index[field] for field in required)
    for row in rows:
        if len(row) <= last_required_idx:
            return False
        if any(str(row[index[field]] or "").strip() == "" for field in required):
            return False
    return True


def _is_display_only_sheet_field(field: object) -> bool:
    return _is_aux_sheet_field(field) or _is_sheet_note_field(field)


def _fields_compatible_for_authoritative_weekly_shell_rebase(
    current_fields: list[str],
    fresh_fields: list[str],
) -> bool:
    if not current_fields or not fresh_fields:
        return False
    shell_fields = {"date_mmdd", "daypart", "menu"}
    current_core = {
        field
        for field in current_fields
        if field in shell_fields or field.startswith("qty.")
    }
    fresh_core = {
        field
        for field in fresh_fields
        if field in shell_fields or field.startswith("qty.")
    }
    if current_core != fresh_core:
        return False
    for field in current_fields:
        if field in shell_fields or field.startswith("qty.") or _is_display_only_sheet_field(field):
            continue
        return False
    for field in fresh_fields:
        if field in shell_fields or field.startswith("qty.") or _is_display_only_sheet_field(field):
            continue
        return False
    return True


def _draft_requires_authoritative_weekly_shell_rebase(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
) -> bool:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        return False
    if not _fresh_sheet_has_authoritative_weekly_shell(fresh_sheet):
        return False
    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    current_rows = _sanitize_semantic_sheet_rows(
        rows_payload=current_sheet.get("rows"),
        fields=current_fields,
    )
    fresh_rows = _sanitize_semantic_sheet_rows(
        rows_payload=fresh_sheet.get("rows"),
        fields=fresh_fields,
    )
    if not _fields_compatible_for_authoritative_weekly_shell_rebase(current_fields, fresh_fields):
        return False
    if not current_fields or not fresh_fields or not current_rows or not fresh_rows:
        return False
    current_index = {field: idx for idx, field in enumerate(current_fields)}
    fresh_index = {field: idx for idx, field in enumerate(fresh_fields)}
    shell_fields = ["date_mmdd", "daypart", "menu"]
    if any(field not in current_index or field not in fresh_index for field in shell_fields):
        return False
    current_shell = [
        tuple(str(row[current_index[field]] or "").strip() for field in shell_fields)
        for row in current_rows
        if len(row) > max(current_index[field] for field in shell_fields)
    ]
    fresh_shell = [
        tuple(str(row[fresh_index[field]] or "").strip() for field in shell_fields)
        for row in fresh_rows
        if len(row) > max(fresh_index[field] for field in shell_fields)
    ]
    return current_fields != fresh_fields or current_shell != fresh_shell


def _draft_requires_authoritative_aux_rebase(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
) -> bool:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        return False
    if not _fresh_sheet_has_authoritative_weekly_shell(fresh_sheet):
        return False
    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    if not _fields_compatible_for_authoritative_weekly_shell_rebase(current_fields, fresh_fields):
        return False
    aux_fields = [
        field
        for field in fresh_fields
        if _is_aux_sheet_field(field) and field in current_fields
    ]
    if not aux_fields:
        return False
    current_rows = _sanitize_semantic_sheet_rows(
        rows_payload=current_sheet.get("rows"),
        fields=current_fields,
    )
    fresh_rows = _sanitize_semantic_sheet_rows(
        rows_payload=fresh_sheet.get("rows"),
        fields=fresh_fields,
    )
    if not current_rows or not fresh_rows:
        return False
    current_index = {field: idx for idx, field in enumerate(current_fields)}
    fresh_index = {field: idx for idx, field in enumerate(fresh_fields)}
    current_by_key: dict[tuple[str, str, str], list[str]] = {}
    for row in current_rows:
        row_key = _sheet_row_identity_key(current_fields, row)
        if row_key is None:
            continue
        current_by_key[row_key] = row
    for fresh_row in fresh_rows:
        row_key = _sheet_row_identity_key(fresh_fields, fresh_row)
        if row_key is None or row_key not in current_by_key:
            continue
        current_row = current_by_key[row_key]
        for field in aux_fields:
            current_idx = current_index.get(field)
            fresh_idx = fresh_index.get(field)
            if current_idx is None or fresh_idx is None:
                continue
            current_value = (
                _field_value_to_str(current_row[current_idx]).strip()
                if current_idx < len(current_row)
                else ""
            )
            fresh_value = (
                _field_value_to_str(fresh_row[fresh_idx]).strip()
                if fresh_idx < len(fresh_row)
                else ""
            )
            if fresh_value and current_value != fresh_value:
                return True
    return False


def _draft_requires_authoritative_quantity_rebase(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
) -> bool:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        return False
    if not _fresh_sheet_has_authoritative_weekly_shell(fresh_sheet):
        return False
    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    if not _fields_compatible_for_authoritative_weekly_shell_rebase(current_fields, fresh_fields):
        return False
    quantity_fields = [
        field
        for field in fresh_fields
        if field.startswith("qty.") and field in current_fields
    ]
    if not quantity_fields:
        return False
    current_rows = _sanitize_semantic_sheet_rows(
        rows_payload=current_sheet.get("rows"),
        fields=current_fields,
    )
    fresh_rows = _sanitize_semantic_sheet_rows(
        rows_payload=fresh_sheet.get("rows"),
        fields=fresh_fields,
    )
    if not current_rows or not fresh_rows:
        return False
    current_index = {field: idx for idx, field in enumerate(current_fields)}
    fresh_index = {field: idx for idx, field in enumerate(fresh_fields)}
    current_by_key: dict[tuple[str, str, str], list[str]] = {}
    for row in current_rows:
        row_key = _sheet_row_identity_key(current_fields, row)
        if row_key is None:
            continue
        current_by_key[row_key] = row
    for fresh_row in fresh_rows:
        row_key = _sheet_row_identity_key(fresh_fields, fresh_row)
        if row_key is None or row_key not in current_by_key:
            continue
        current_row = current_by_key[row_key]
        for field in quantity_fields:
            current_idx = current_index.get(field)
            fresh_idx = fresh_index.get(field)
            if current_idx is None or fresh_idx is None:
                continue
            current_value = (
                _field_value_to_str(current_row[current_idx]).strip()
                if current_idx < len(current_row)
                else ""
            )
            fresh_value = (
                _field_value_to_str(fresh_row[fresh_idx]).strip()
                if fresh_idx < len(fresh_row)
                else ""
            )
            if current_value != fresh_value:
                return True
    return False


def _draft_requires_authoritative_schema_upgrade(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
) -> bool:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        return False
    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    if not _fields_compatible_for_authoritative_weekly_shell_rebase(current_fields, fresh_fields):
        return False
    return current_fields != fresh_fields or _draft_requires_authoritative_aux_rebase(
        current_sheet,
        fresh_sheet,
    )


def _should_prune_unmatched_rows_on_semantic_refresh(draft: dict[str, Any] | None) -> bool:
    if not isinstance(draft, dict):
        return False
    draft_state = str(draft.get("draft_state") or "").strip().lower()
    if draft_state == "auto_apply_blocked":
        return True
    blockers = {
        str(item).strip()
        for item in (draft.get("blockers_json") or [])
        if str(item).strip()
    }
    return bool(blockers & _SEMANTIC_REFRESH_PRUNE_BLOCKERS)


def _filter_blockers_for_semantic_refresh(blockers: list[str] | None) -> list[str]:
    preserved: list[str] = []
    seen: set[str] = set()
    for item in blockers or []:
        token = str(item or "").strip()
        if not token or token in _SEMANTIC_REFRESH_PRUNE_BLOCKERS or token in seen:
            continue
        seen.add(token)
        preserved.append(token)
    return preserved


def _merge_current_draft_quantity_values_into_semantic_sheet(
    current_sheet: dict[str, Any] | None,
    fresh_sheet: dict[str, Any] | None,
    *,
    copy_shared_quantity_values: bool = False,
) -> dict[str, Any] | None:
    if not isinstance(current_sheet, dict) or not isinstance(fresh_sheet, dict):
        return fresh_sheet if isinstance(fresh_sheet, dict) else current_sheet

    current_fields = [str(field).strip() for field in (current_sheet.get("fields") or []) if str(field).strip()]
    fresh_fields = [str(field).strip() for field in (fresh_sheet.get("fields") or []) if str(field).strip()]
    current_rows = [list(row) for row in (current_sheet.get("rows") or []) if isinstance(row, list)]
    fresh_rows = [list(row) for row in (fresh_sheet.get("rows") or []) if isinstance(row, list)]
    if not current_fields or not fresh_fields or not current_rows or not fresh_rows:
        return fresh_sheet

    current_index = {field: idx for idx, field in enumerate(current_fields)}
    fresh_index = {field: idx for idx, field in enumerate(fresh_fields)}
    current_quantity_fields = [field for field in current_fields if field.startswith("qty.")]
    fresh_quantity_fields = [field for field in fresh_fields if field.startswith("qty.")]
    if current_quantity_fields == fresh_quantity_fields and not copy_shared_quantity_values:
        return fresh_sheet
    shared_quantity_fields = [
        field
        for field in current_quantity_fields
        if field.startswith("qty.") and field in fresh_index
    ]
    quantity_pairs: list[tuple[int, int]] = [
        (current_index[field], fresh_index[field])
        for field in shared_quantity_fields
    ]
    if copy_shared_quantity_values:
        remaining_current_quantity_fields = [
            field for field in current_quantity_fields if field not in shared_quantity_fields
        ]
        remaining_fresh_quantity_fields = [
            field for field in fresh_quantity_fields if field not in shared_quantity_fields
        ]
        for current_field, fresh_field in zip(
            remaining_current_quantity_fields,
            remaining_fresh_quantity_fields,
        ):
            quantity_pairs.append((current_index[current_field], fresh_index[fresh_field]))
    if not quantity_pairs:
        return fresh_sheet
    preserved_fresh_quantity_indexes = {fresh_idx for _current_idx, fresh_idx in quantity_pairs}

    current_row_ids = [str(item).strip() for item in (current_sheet.get("row_ids") or []) if str(item).strip()]
    fresh_row_ids = [str(item).strip() for item in (fresh_sheet.get("row_ids") or []) if str(item).strip()]
    if len(fresh_row_ids) < len(fresh_rows):
        fresh_row_ids.extend([f"row-{idx + 1}" for idx in range(len(fresh_row_ids), len(fresh_rows))])

    current_by_key: dict[tuple[str, str, str], tuple[list[Any], str | None]] = {}
    for idx, row in enumerate(current_rows):
        row_key = _sheet_row_identity_key(current_fields, row)
        if row_key is None:
            continue
        row_id = current_row_ids[idx] if idx < len(current_row_ids) else None
        current_by_key[row_key] = (row, row_id)

    if not current_by_key:
        return fresh_sheet

    merged_rows: list[list[Any]] = []
    merged_row_ids: list[str] = []
    for idx, fresh_row in enumerate(fresh_rows):
        merged_row = list(fresh_row)
        merged_row_id = fresh_row_ids[idx] if idx < len(fresh_row_ids) else f"row-{idx + 1}"
        row_key = _sheet_row_identity_key(fresh_fields, fresh_row)
        if row_key is not None and row_key in current_by_key:
            current_row, current_row_id = current_by_key[row_key]
            for field_name in fresh_quantity_fields:
                fresh_idx = fresh_index[field_name]
                if fresh_idx in preserved_fresh_quantity_indexes:
                    continue
                while len(merged_row) <= fresh_idx:
                    merged_row.append("")
                merged_row[fresh_idx] = ""
            for current_idx, fresh_idx in quantity_pairs:
                current_value = current_row[current_idx] if current_idx < len(current_row) else ""
                while len(merged_row) <= fresh_idx:
                    merged_row.append("")
                if _sheet_cell_has_value(current_value):
                    merged_row[fresh_idx] = current_value
            if current_row_id:
                merged_row_id = current_row_id
        merged_rows.append(merged_row)
        merged_row_ids.append(merged_row_id)

    merged = dict(fresh_sheet)
    merged["rows"] = merged_rows
    merged["row_ids"] = merged_row_ids
    return merged


def _maybe_refresh_semantic_sheet_draft(
    order_id: str,
    draft: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(draft, dict):
        return draft
    if _draft_record_has_forced_repair_mode(draft):
        return draft
    draft_sheet_json = draft.get("draft_sheet_json")
    if not isinstance(draft_sheet_json, dict):
        return draft
    fresh_sheet = _build_best_available_semantic_draft(order_id, use_saved_draft=False)
    if not isinstance(fresh_sheet, dict) or _draft_fields_look_generic(fresh_sheet.get("fields")):
        return draft
    clean_saved_draft = apply_gate_service.has_clean_saved_draft(draft)
    prune_unmatched_rows = _should_prune_unmatched_rows_on_semantic_refresh(draft)
    authoritative_shell_rebase = _draft_requires_authoritative_weekly_shell_rebase(
        draft_sheet_json,
        fresh_sheet,
    )
    merged_sheet = _merge_saved_draft_into_semantic_sheet(
        draft_sheet_json,
        fresh_sheet,
        append_unmatched_current_rows=not prune_unmatched_rows,
        merge_current_warnings=False,
        preserve_blank_quantity_values=clean_saved_draft and not authoritative_shell_rebase,
        preserve_current_quantity_values=True,
    )
    if not isinstance(merged_sheet, dict):
        return draft
    current_blockers = [str(item).strip() for item in (draft.get("blockers_json") or []) if str(item).strip()]
    current_warning_rows = [str(item).strip() for item in (draft.get("warnings_json") or []) if str(item).strip()]
    next_blockers = _filter_blockers_for_semantic_refresh(
        current_blockers
    )
    if prune_unmatched_rows:
        next_warnings = [str(item).strip() for item in (merged_sheet.get("warnings") or []) if str(item).strip()]
    else:
        next_warnings = list(current_warning_rows)
        merged_sheet["warnings"] = list(next_warnings)
    if (
        draft_sheet_json.get("fields") == merged_sheet.get("fields")
        and draft_sheet_json.get("header") == merged_sheet.get("header")
        and draft_sheet_json.get("rows") == merged_sheet.get("rows")
        and (
            prune_unmatched_rows is False
            or [str(item).strip() for item in (draft_sheet_json.get("warnings") or []) if str(item).strip()] == next_warnings
        )
        and current_blockers == next_blockers
        and current_warning_rows == next_warnings
    ):
        return draft
    refreshed = persist_sheet_draft(
        order_id=order_id,
        draft_sheet_json=merged_sheet,
        draft_state=str(draft.get("draft_state") or "draft_ready").strip() or "draft_ready",
        blockers=next_blockers,
        warnings=next_warnings,
        latest_patch_candidate_id=str(draft.get("latest_patch_candidate_id") or "").strip() or None,
        edited_by="semantic-sheet-refresh",
    )
    return refreshed if isinstance(refreshed, dict) else draft


def _maybe_upgrade_generic_sheet_draft(
    order_id: str,
    draft: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(draft, dict):
        return draft
    draft_sheet_json = draft.get("draft_sheet_json")
    if not isinstance(draft_sheet_json, dict):
        return draft
    if not _draft_fields_look_generic(draft_sheet_json.get("fields")):
        return draft
    upgraded_sheet = _build_best_available_semantic_draft(order_id)
    if not isinstance(upgraded_sheet, dict):
        return draft
    upgraded = persist_sheet_draft(
        order_id=order_id,
        draft_sheet_json=upgraded_sheet,
        draft_state=str(draft.get("draft_state") or "draft_ready").strip() or "draft_ready",
        blockers=[str(item).strip() for item in (draft.get("blockers_json") or []) if str(item).strip()],
        warnings=[str(item).strip() for item in (draft.get("warnings_json") or []) if str(item).strip()],
        latest_patch_candidate_id=str(draft.get("latest_patch_candidate_id") or "").strip() or None,
        edited_by="semantic-sheet-upgrade",
    )
    return upgraded if isinstance(upgraded, dict) else draft


def get_latest_sheet_draft(
    order_id: str,
    *,
    backfill_from_revision: bool = True,
    upgrade_generic_from_sheet: bool = False,
) -> Optional[dict]:
    # `get_latest_sheet_draft` is the persisted-draft read path only.
    # Current semantic/editor surfaces must use `get_current_sheet_context`.
    _ = backfill_from_revision
    _ = upgrade_generic_from_sheet
    return draft_sheet_service.get_latest_sheet_draft(order_id)


def get_cached_hakodate_assignment_preview(order_id: str) -> Optional[dict[str, Any]]:
    latest_payload = _load_hakodate_assignment_source_payload(order_id)
    if (
        _payload_has_current_hakodate_canonical_pipeline(latest_payload)
        and _payload_has_hakodate_target_cells(latest_payload)
        and _payload_has_hakodate_evidence_records(latest_payload, order_id=order_id)
    ):
        assignment, assignment_error = build_order_hakodate_assignment(
            order_id,
            strategy="hakodate",
            allow_artifact_repair=False,
        )
        if isinstance(assignment, dict) and not assignment_error:
            return assignment
    cached_payload = _load_order_ocr_cache(order_id)
    if not isinstance(cached_payload, dict):
        return None
    preview = cached_payload.get("hakodate_assignment_preview")
    if not isinstance(preview, dict) or not isinstance(preview.get("assignment"), dict):
        return None
    if str(preview.get("version") or "").strip() != HAKODATE_CANONICAL_PIPELINE_VERSION:
        return None
    preview_fingerprint = str(preview.get("fingerprint") or "").strip()
    if not preview_fingerprint:
        return None
    overlay = cached_payload.get("hakodate_overlay")
    if isinstance(overlay, dict):
        overlay_fingerprint = str(overlay.get("fingerprint") or "").strip()
        overlay_producer = str(overlay.get("producer") or "").strip()
        if overlay_fingerprint and overlay_fingerprint != preview_fingerprint:
            return None
        overlay_version = str(overlay.get("version") or "").strip()
        if overlay_version and overlay_version != HAKODATE_CANONICAL_PIPELINE_VERSION:
            return None
        if overlay_producer and overlay_producer != "hakodate_best_method_pipeline":
            return None
    return preview["assignment"]


def _load_hakodate_assignment_source_payload(order_id: str) -> dict[str, Any]:
    latest_evidence = get_latest_ocr_evidence_run(order_id, backfill_from_cache=False)
    latest_payload = latest_evidence.get("payload_json") if isinstance(latest_evidence, dict) else None
    if (
        isinstance(latest_payload, dict)
        and _payload_has_current_hakodate_canonical_pipeline(latest_payload)
        and _payload_has_hakodate_target_cells(latest_payload)
        and _payload_has_hakodate_evidence_records(latest_payload, order_id=order_id)
    ):
        return evidence_manifest_service.ensure_evidence_manifest(dict(latest_payload))
    cached_payload = _load_order_ocr_cache(order_id)
    return cached_payload if isinstance(cached_payload, dict) else {}


def _load_latest_hakodate_overlay_source(
    order_id: str,
) -> tuple[dict[str, Any], str | None, bool]:
    latest_evidence = get_latest_ocr_evidence_run(order_id, backfill_from_cache=False)
    latest_payload = latest_evidence.get("payload_json") if isinstance(latest_evidence, dict) else None
    if (
        isinstance(latest_payload, dict)
        and _payload_has_current_hakodate_canonical_pipeline(latest_payload)
        and _payload_has_hakodate_target_cells(latest_payload)
    ):
        return (
            evidence_manifest_service.ensure_evidence_manifest(dict(latest_payload)),
            str(latest_evidence.get("id") or "").strip() or None,
            True,
        )
    cached_payload = _load_order_ocr_cache(order_id)
    return cached_payload if isinstance(cached_payload, dict) else {}, None, False


def _latest_hakodate_evidence_available(order_id: str) -> bool:
    latest_evidence = get_latest_ocr_evidence_run(order_id, backfill_from_cache=False)
    latest_payload = latest_evidence.get("payload_json") if isinstance(latest_evidence, dict) else None
    return (
        isinstance(latest_payload, dict)
        and _payload_has_current_hakodate_canonical_pipeline(latest_payload)
        and _payload_has_hakodate_target_cells(latest_payload)
        and _payload_has_hakodate_evidence_records(latest_payload, order_id=order_id)
    )


def ensure_hakodate_evidence_draft_current(
    order_id: str,
    *,
    edited_by: str | None = None,
) -> tuple[Optional[dict], Optional[str]]:
    """Keep visible sheet surfaces on the Hakodate evidence projection when it exists."""
    current_draft = get_latest_sheet_draft(
        order_id,
        backfill_from_revision=False,
        upgrade_generic_from_sheet=False,
    )
    if _draft_payload_has_hakodate_evidence_projection(current_draft):
        return current_draft, None

    projected_bundle, projected_error = build_order_hakodate_projected_sheet(
        order_id,
        strategy="hakodate",
    )
    draft_payload = (
        projected_bundle.get("projected_sheet")
        if isinstance(projected_bundle, dict) and isinstance(projected_bundle.get("projected_sheet"), dict)
        else None
    )
    if isinstance(draft_payload, dict):
        latest_evidence = get_latest_ocr_evidence_run(order_id, backfill_from_cache=False)
        persisted = _persist_sheet_draft_with_base_evidence(
            order_id=order_id,
            draft_sheet_json=draft_payload,
            draft_state="draft_blocked" if draft_payload.get("blockers") else "draft_ready",
            blockers=[str(item).strip() for item in (draft_payload.get("blockers") or []) if str(item).strip()],
            warnings=[str(item).strip() for item in (draft_payload.get("warnings") or []) if str(item).strip()],
            evidence_run_override=latest_evidence if isinstance(latest_evidence, dict) else None,
            edited_by=edited_by or "auto-hakodate-evidence-current-draft",
        )
        if isinstance(persisted, dict):
            return persisted, None
    if projected_error in {"order_not_found", "facility_missing", "facility_not_found", "template_unresolved"}:
        return None, projected_error
    return current_draft, None


def get_hakodate_pipeline_job_status(order_id: str) -> dict[str, Any]:
    normalized_order_id = str(order_id or "").strip()
    job = get_ocr_job(f"OCR-{normalized_order_id}") if normalized_order_id else None
    if not isinstance(job, dict):
        return describe_ocr_job_state(None)
    request_mode = get_job_request_mode(job)
    if request_mode and request_mode not in {"ocr_rerun", "ocr_reparse", "llm_reparse"}:
        return describe_ocr_job_state(None)
    state = describe_ocr_job_state(job)
    metrics = job.get("metrics")
    metrics = metrics if isinstance(metrics, dict) else {}
    return {
        **state,
        "request_mode": request_mode or None,
        "processing_stage": str(metrics.get("processing_stage") or "").strip() or None,
        "result_state": str(metrics.get("result_state") or "").strip() or None,
        "error": (
            str(metrics.get("error") or "").strip()
            or str(job.get("error_message") or "").strip()
            or None
        ),
        "output_reference": str(job.get("output_reference") or "").strip() or None,
    }


def get_cached_hakodate_overlay_preview(order_id: str) -> dict[str, Any]:
    job_status = get_hakodate_pipeline_job_status(order_id)
    overlay_payload, evidence_run_id, has_latest_hakodate_evidence = _load_latest_hakodate_overlay_source(order_id)
    if not isinstance(overlay_payload, dict):
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_artifact_missing"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_artifact_missing"),
            "overlay_url": None,
            "overlay_uri": None,
            "assignment": None,
            "source_evidence_run_id": evidence_run_id,
            "job_status": job_status,
        }
    overlay = overlay_payload.get("hakodate_overlay")
    if not isinstance(overlay, dict):
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_artifact_missing"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_artifact_missing"),
            "overlay_url": None,
            "overlay_uri": None,
            "assignment": get_cached_hakodate_assignment_preview(order_id),
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    overlay_producer = str(overlay.get("producer") or "").strip()
    overlay_uri = str(overlay.get("uri") or "").strip()
    overlay_fingerprint = str(overlay.get("fingerprint") or "").strip()
    overlay_version = str(overlay.get("version") or "").strip()
    if (
        overlay_producer != "hakodate_best_method_pipeline"
        or not _hakodate_version_matches_current(
            overlay_version,
            allow_versionless=has_latest_hakodate_evidence,
        )
    ):
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_render_unavailable"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_render_unavailable"),
            "overlay_url": None,
            "overlay_uri": overlay_uri or None,
            "assignment": None,
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    if not overlay_uri or not overlay_fingerprint:
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_artifact_missing"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_artifact_missing"),
            "overlay_url": None,
            "overlay_uri": overlay_uri or None,
            "assignment": get_cached_hakodate_assignment_preview(order_id),
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    assignment = get_cached_hakodate_assignment_preview(order_id)
    if not isinstance(assignment, dict):
        return {
            "status": "blocked",
            "blockers": ["hakodate_assignment_preview_missing"],
            "message": _describe_hakodate_overlay_blocker("hakodate_assignment_unavailable"),
            "overlay_url": None,
            "overlay_uri": overlay_uri,
            "assignment": None,
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    overlay_url = _signed_url_from_uri(overlay_uri)
    if not overlay_url:
        return {
            "status": "blocked",
            "blockers": ["hakodate_overlay_render_unavailable"],
            "message": _describe_hakodate_overlay_blocker("hakodate_overlay_render_unavailable"),
            "overlay_url": None,
            "overlay_uri": overlay_uri,
            "assignment": assignment,
            "source_evidence_run_id": evidence_run_id,
            "latest_hakodate_evidence": has_latest_hakodate_evidence,
            "job_status": job_status,
        }
    return {
        "status": "ready",
        "blockers": list(assignment.get("blockers") or []),
        "message": "",
        "overlay_uri": overlay_uri,
        "overlay_url": overlay_url,
        "assignment": assignment,
        "source_evidence_run_id": evidence_run_id,
        "latest_hakodate_evidence": has_latest_hakodate_evidence,
        "job_status": job_status,
    }


def get_hakodate_overlay_preview(order_id: str) -> dict[str, Any]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return {
                "status": "blocked",
                "blockers": ["order_not_found"],
                "message": "order not found",
                "overlay_url": None,
                "overlay_uri": None,
                "assignment": None,
            }
        document_uri = str(order.document_uri or "").strip() or None
    return _build_hakodate_overlay_preview(
        order_id=order_id,
        document_uri=document_uri,
    )


def _build_initial_draft_from_sheet_payload(
    order_id: str,
    sheet_payload: dict[str, Any] | None,
) -> Optional[dict[str, Any]]:
    if not isinstance(sheet_payload, dict):
        return None
    fields = [str(field).strip() for field in (sheet_payload.get("fields") or []) if str(field).strip()]
    blockers = [str(item).strip() for item in (sheet_payload.get("blockers") or []) if str(item).strip()]
    warnings = [str(item).strip() for item in (sheet_payload.get("warnings") or []) if str(item).strip()]
    rows = _sanitize_semantic_sheet_rows(
        rows_payload=_sanitize_revision_rows(rows_payload=sheet_payload.get("rows"), fields=fields),
        fields=fields,
    )
    allow_blocked_empty_payload = (
        not rows
        and bool(fields)
        and bool(
            set(blockers)
            | {
                warning
                for warning in warnings
                if warning in {
                    "menu_entries_missing",
                    "monthly_menu_object_missing",
                    "monthly_menu_facility_scope_missing",
                    "template_unresolved",
                    "template_resolution_blocked",
                    "ocr_evidence_recovery_required",
                }
            }
        )
    ) or (bool(blockers) and not fields and not rows)
    if (not fields or not rows) and not allow_blocked_empty_payload:
        return None
    row_ids = [str(item).strip() for item in (sheet_payload.get("row_ids") or []) if str(item).strip()]
    if len(row_ids) < len(rows):
        row_ids.extend([f"row-{idx + 1}" for idx in range(len(row_ids), len(rows))])
    header = [str(cell or "").strip() for cell in (sheet_payload.get("header") or [])]
    if len(header) < len(fields):
        header.extend([_field_label(field) for field in fields[len(header) :]])
    source = str(sheet_payload.get("source") or "ocr_sheet").strip() or "ocr_sheet"
    return {
        "order_id": order_id,
        "source": source,
        "fields": fields,
        "header": header[: len(fields)],
        "rows": rows,
        "row_ids": row_ids[: len(rows)],
        "blockers": blockers,
        "warnings": warnings,
        "week_id": str(sheet_payload.get("week_id") or "").strip() or None,
        "resolved_week_id": str(
            sheet_payload.get("resolved_week_id") or sheet_payload.get("week_id") or ""
        ).strip() or None,
        "draft_state": str(
            sheet_payload.get("draft_state")
            or ("draft_blocked" if blockers else "draft_ready")
        ).strip()
        or ("draft_blocked" if blockers else "draft_ready"),
        "base_template_resolution_id": str(sheet_payload.get("base_template_resolution_id") or "").strip() or None,
        "menu_diagnostics": (
            dict(sheet_payload.get("menu_diagnostics"))
            if isinstance(sheet_payload.get("menu_diagnostics"), dict)
            else None
        ),
        "row_diagnostics": list(sheet_payload.get("row_diagnostics") or [])
        if isinstance(sheet_payload.get("row_diagnostics"), list)
        else [],
        "seed_source": str(sheet_payload.get("seed_source") or "").strip() or None,
        "enrichment_source": str(sheet_payload.get("enrichment_source") or "").strip() or None,
    }


def _build_best_available_semantic_draft_with_error(
    order_id: str,
    *,
    use_saved_draft: bool = True,
    evidence_run_override: dict[str, Any] | None = None,
) -> tuple[Optional[dict[str, Any]], Optional[str]]:
    sheet_payload, sheet_error = get_ocr_sheet(
        order_id,
        use_saved_draft=use_saved_draft,
        evidence_run_override=evidence_run_override,
    )
    candidates: list[dict[str, Any]] = []
    if isinstance(sheet_payload, dict):
        candidates.append(sheet_payload)
    if sheet_error in _RECOVERABLE_OCR_SHEET_ERRORS:
        recovered, recover_error = build_recoverable_ocr_sheet_payload(
            order_id,
            sheet_error,
            use_saved_draft=use_saved_draft,
            evidence_run_override=evidence_run_override,
        )
        if recover_error is None and isinstance(recovered, dict):
            candidates.append(recovered)
    for candidate in candidates:
        draft_payload = _build_initial_draft_from_sheet_payload(order_id, candidate)
        if not isinstance(draft_payload, dict):
            continue
        if not _draft_fields_look_generic(draft_payload.get("fields")):
            return draft_payload, None
        blocker_tokens = {
            str(item).strip()
            for item in (draft_payload.get("blockers") or [])
            if str(item).strip()
        }
        warning_tokens = {
            str(item).strip()
            for item in (draft_payload.get("warnings") or [])
            if str(item).strip()
        }
        if blocker_tokens & {"template_unresolved"} or warning_tokens & {
            "template_unresolved",
            "template_resolution_blocked",
        }:
            return draft_payload, None
    return None, sheet_error or "candidate_preview_unavailable"


def _build_best_available_semantic_draft(
    order_id: str,
    *,
    use_saved_draft: bool = True,
    evidence_run_override: dict[str, Any] | None = None,
) -> Optional[dict[str, Any]]:
    draft_payload, _error = _build_best_available_semantic_draft_with_error(
        order_id,
        use_saved_draft=use_saved_draft,
        evidence_run_override=evidence_run_override,
    )
    return draft_payload


def _candidate_preview_signature(
    order_id: str,
    payload: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return None
    flattened = flatten_current_sheet_payload(order_id, payload, include_meta=False)
    if not isinstance(flattened, dict):
        return None
    return {
        "sheet_digest": _sheet_digest(
            fields=flattened.get("fields"),
            header=flattened.get("header"),
            rows_payload=flattened.get("rows"),
            row_ids=flattened.get("row_ids"),
        ),
        "source": str(flattened.get("source") or "").strip() or None,
        "draft_state": str(flattened.get("draft_state") or "").strip() or None,
        "warnings": tuple(_dedupe_str_tokens(flattened.get("warnings") or [])),
        "blockers": tuple(_dedupe_str_tokens(flattened.get("blockers") or [])),
    }


def resolve_candidate_evidence_preview_contract(
    order_id: str,
    *,
    candidate_evidence_run: dict[str, Any] | None = None,
    candidate_evidence_run_id: str | None = None,
    current_sheet_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    normalized_order_id = str(order_id or "").strip()
    resolved_candidate_evidence_run_id = (
        str(candidate_evidence_run_id or "").strip()
        or str((candidate_evidence_run or {}).get("id") or "").strip()
        or None
    )
    resolved_candidate_evidence_run = (
        candidate_evidence_run
        if isinstance(candidate_evidence_run, dict)
        else get_ocr_evidence_run(resolved_candidate_evidence_run_id or "")
    )
    result: dict[str, Any] = {
        "order_id": normalized_order_id,
        "candidate_evidence_run_id": resolved_candidate_evidence_run_id,
        "status": "candidate_not_found",
        "error": "candidate_not_found",
        "previewable": False,
        "has_material_diff": False,
        "preview_draft": None,
        "draft_payload": None,
    }
    if not normalized_order_id or not isinstance(resolved_candidate_evidence_run, dict):
        return result

    current_context = (
        current_sheet_context
        if isinstance(current_sheet_context, dict)
        else get_current_sheet_context(
            normalized_order_id,
            refresh_draft_from_semantic=True,
            upgrade_generic_from_sheet=True,
            backfill_from_revision=False,
        )
    )
    current_base_evidence_run_id = (
        str((current_context or {}).get("base_evidence_run_id") or "").strip() or None
    )
    if current_base_evidence_run_id and current_base_evidence_run_id == resolved_candidate_evidence_run_id:
        return {
            **result,
            "status": "already_current",
            "error": "already_current",
        }

    draft_payload, build_error = _build_best_available_semantic_draft_with_error(
        normalized_order_id,
        use_saved_draft=False,
        evidence_run_override=resolved_candidate_evidence_run,
    )
    if not isinstance(draft_payload, dict):
        return {
            **result,
            "status": "candidate_preview_blocked",
            "error": build_error or "candidate_preview_unavailable",
        }

    transient = _build_transient_draft_record(normalized_order_id, draft_payload)
    if not isinstance(transient, dict):
        return {
            **result,
            "status": "candidate_preview_blocked",
            "error": "candidate_preview_unavailable",
            "draft_payload": draft_payload,
        }

    current_signature = _candidate_preview_signature(normalized_order_id, current_context)
    candidate_signature = _candidate_preview_signature(normalized_order_id, transient)
    if current_signature is not None and current_signature == candidate_signature:
        return {
            **result,
            "status": "already_current",
            "error": "already_current",
            "draft_payload": draft_payload,
        }

    return {
        **result,
        "status": "previewable",
        "error": None,
        "previewable": True,
        "has_material_diff": True,
        "preview_draft": transient,
        "draft_payload": draft_payload,
    }


def _load_sheet_week_hints(facility_id: str | None) -> list[str]:
    normalized_facility_id = str(facility_id or "").strip() or None
    facility_week_hint = None
    global_week_hint = None
    with session_scope() as session:
        if normalized_facility_id:
            facility_week_hint = (
                session.execute(
                    select(Order.week_code)
                    .where(Order.facility_code == normalized_facility_id, Order.week_code.is_not(None))
                    .order_by(Order.received_at.desc())
                    .limit(1)
                )
                .scalars()
                .first()
            )
        global_week_hint = (
            session.execute(
                select(Order.week_code)
                .where(Order.week_code.is_not(None))
                .order_by(Order.received_at.desc())
                .limit(1)
            )
            .scalars()
            .first()
        )
    return [hint for hint in [facility_week_hint, global_week_hint] if hint]


def _load_sheet_order_lines(order_id: str) -> list[dict[str, Any]]:
    with session_scope() as session:
        order = session.get(Order, order_id)
        if not order:
            return []
        return [
            {
                "id": line.id,
                "line_id": line.line_id,
                "date": line.date,
                "daypart": line.daypart,
                "menu_name": line.menu_name,
                "diet_type": line.diet_type,
                "area_id": line.area_id,
                "bag_type": line.bag_type,
                "quantity_original": line.quantity_original,
                "quantity_corrected": line.quantity_corrected,
                "change_note": line.change_note,
            }
            for line in (order.lines or [])
        ]


def _build_blocked_sheet_payload(
    *,
    order_id: str,
    facility_id: str | None,
    week_id: str | None,
    fields: list[str] | None = None,
    header: list[str] | None = None,
    blockers: list[str] | None = None,
    warnings: list[str] | None = None,
    source: str = "weekly_menu_skeleton",
    base_template_resolution_id: str | None = None,
    menu_diagnostics: dict[str, Any] | None = None,
    base_evidence_run_id: str | None = None,
) -> dict[str, Any]:
    normalized_fields = [str(field).strip() for field in (fields or []) if str(field).strip()]
    normalized_header = list(header or [])
    if len(normalized_header) < len(normalized_fields):
        normalized_header.extend([_field_label(field) for field in normalized_fields[len(normalized_header) :]])
    normalized_blockers = _dedupe_str_tokens(blockers or [])
    normalized_warnings = _dedupe_str_tokens(warnings or [])
    return {
        "order_id": order_id,
        "facility_id": facility_id,
        "week_id": week_id,
        "resolved_week_id": week_id,
        "fields": normalized_fields,
        "header": normalized_header[: len(normalized_fields)],
        "rows": [],
        "row_ids": [],
        "quantity_column_count": len([field for field in normalized_fields if field.startswith("qty.")]),
        "source": source,
        "seed_source": "weekly_menu",
        "enrichment_source": None,
        "warnings": normalized_warnings,
        "blockers": normalized_blockers,
        "draft_state": "draft_blocked",
        "base_template_resolution_id": base_template_resolution_id,
        "base_evidence_run_id": base_evidence_run_id,
        "menu_diagnostics": dict(menu_diagnostics or {}),
        "row_diagnostics": [],
        "projection_diagnostics": {},
        "cell_issues": [],
        "issue_summary": {
            "review_required_cell_count": 0,
            "issue_codes": [],
        },
        "ocr_numeric_cell_items": [],
        "ocr_numeric_cell_summary": _empty_ocr_numeric_cell_summary(),
        "trace": {
            "rows": [],
            "mapped_mode": "blocked",
        },
    }


def _canonical_blocked_sheet_source(
    *,
    fields: list[str] | None,
    template_error: str | None = None,
    field_error: str | None = None,
) -> str:
    normalized_fields = [str(field).strip() for field in (fields or []) if str(field).strip()]
    if not normalized_fields or _draft_fields_look_generic(normalized_fields):
        return "weekly_menu_blocked"
    return "review_blocked"


def _build_canonical_bootstrap_sheet(
    order_id: str,
    *,
    evidence_run_override: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, str | None]:
    order_payload = get_order_by_id(order_id)
    if not isinstance(order_payload, dict):
        return None, "order_not_found"
    facility_id = str(order_payload.get("facility") or "").strip() or None
    if not facility_id:
        return None, "facility_missing"
    resolved_week_id = (
        str(order_payload.get("persisted_week_value") or "").strip()
        or str(order_payload.get("week_value") or "").strip()
        or str(order_payload.get("week") or "").strip()
        or None
    )
    if not resolved_week_id:
        return None, "week_unresolved"

    base_evidence_run = (
        evidence_run_override
        if isinstance(evidence_run_override, dict)
        else get_latest_ocr_evidence_run(order_id, backfill_from_cache=True)
    )
    received_at_value = _parse_iso_datetime_value(order_payload.get("received_at")) or datetime.utcnow()
    cached_payload = _load_order_ocr_cache(order_id)
    facility_template = _resolve_order_fax_template(order_id)
    ocr_payload = None
    if isinstance(base_evidence_run, dict) and isinstance(base_evidence_run.get("payload_json"), dict):
        ocr_payload = evidence_manifest_service.ensure_evidence_manifest(
            dict(base_evidence_run.get("payload_json") or {})
        )
        ocr_payload = _merge_legacy_first_pass_payload(
            ocr_payload,
            base_evidence_run,
            cached_payload if isinstance(cached_payload, dict) else None,
            template=facility_template,
        )
        ocr_payload = _annotate_payload_with_template_field_schema(ocr_payload, facility_template)
        ocr_payload = _augment_payload_with_candidate_resolution(order_id, ocr_payload)
        if isinstance(ocr_payload, dict):
            ocr_payload = evidence_manifest_service.ensure_evidence_manifest(dict(ocr_payload))

    facility_config, template, effective_template_id, template_error = _resolve_effective_sheet_template(
        order_id=order_id,
        facility_id=facility_id,
        ocr_payload=None,
        draft_template_id=None,
        allow_workflow_resolution=False,
        log_context="Canonical current sheet template lookup failed",
    )
    if not isinstance(facility_config, dict):
        return None, "facility_not_found"
    if not isinstance(template, dict):
        blocked_payload = _build_blocked_sheet_payload(
            order_id=order_id,
            facility_id=facility_id,
            week_id=resolved_week_id,
            blockers=[template_error or "template_unresolved"],
            source=_canonical_blocked_sheet_source(
                fields=None,
                template_error=template_error or "template_unresolved",
            ),
            base_template_resolution_id=effective_template_id,
            base_evidence_run_id=str((base_evidence_run or {}).get("id") or "").strip() or None,
        )
        return blocked_payload, None

    fields, field_index = _build_sheet_fields_and_indexes(template)
    field_error = _validate_sheet_template_fields(fields)
    header = _sheet_header_from_template(fields, template)
    if field_error:
        blocked_payload = _build_blocked_sheet_payload(
            order_id=order_id,
            facility_id=facility_id,
            week_id=resolved_week_id,
            fields=fields,
            header=header,
            blockers=[field_error],
            source=_canonical_blocked_sheet_source(
                fields=fields,
                field_error=field_error,
            ),
            base_template_resolution_id=effective_template_id,
            base_evidence_run_id=str((base_evidence_run or {}).get("id") or "").strip() or None,
        )
        return blocked_payload, None

    menu_diagnostics = _build_monthly_menu_diagnostics(
        week_id=resolved_week_id,
        facility_id=facility_id,
    )
    order_lines = _load_sheet_order_lines(order_id)
    entries, source = _build_sheet_menu_entries(
        order_id=order_id,
        week_id=resolved_week_id,
        facility_id=facility_id,
        order_lines=order_lines,
        ocr_payload=ocr_payload,
        template=template,
        received_at=received_at_value,
    )
    if not entries:
        blocked_codes = [
            str(item).strip()
            for item in (menu_diagnostics.get("order_codes") or [])
            if str(item).strip()
        ] or ["menu_entries_missing"]
        blocked_payload = _build_blocked_sheet_payload(
            order_id=order_id,
            facility_id=facility_id,
            week_id=resolved_week_id,
            fields=fields,
            header=header,
            blockers=blocked_codes,
            source=_canonical_blocked_sheet_source(fields=fields),
            base_template_resolution_id=effective_template_id,
            menu_diagnostics=menu_diagnostics,
            base_evidence_run_id=str((base_evidence_run or {}).get("id") or "").strip() or None,
        )
        return blocked_payload, None

    structured_rows, source = _build_rows_from_menu_entries(
        entries=entries,
        fields=fields,
        field_index=field_index,
        header=header,
        line_dates=set(),
        source=source,
        payload_dates=None,
        payload_row_count=0,
        scope_anchor_date=None,
    )
    if not structured_rows:
        blocked_payload = _build_blocked_sheet_payload(
            order_id=order_id,
            facility_id=facility_id,
            week_id=resolved_week_id,
            fields=fields,
            header=header,
            blockers=["menu_entries_missing"],
            source=_canonical_blocked_sheet_source(fields=fields),
            base_template_resolution_id=effective_template_id,
            menu_diagnostics=menu_diagnostics,
            base_evidence_run_id=str((base_evidence_run or {}).get("id") or "").strip() or None,
        )
        return blocked_payload, None

    quantity_index = _build_sheet_quantity_index(fields)
    rows = _clone_sheet_rows(structured_rows)
    mapped_mode = "blank"
    mapped_count = 0
    has_order_lines = False
    payload_rows: list[list[str]] = []
    payload_unstructured_qty: list[str] = []
    payload_explicit_quantity_pairs: list[tuple[int, int]] = []
    if isinstance(ocr_payload, dict):
        payload_rows = _extract_sheet_rows_from_payload(ocr_payload, template)
        payload_unstructured_qty = _extract_payload_unstructured_quantity_candidates(ocr_payload)
        payload_explicit_quantity_pairs = _resolved_quantity_source_target_pairs(ocr_payload, fields)

    if order_lines:
        has_order_lines = True
        _apply_order_line_quantities_to_sheet_rows(
            rows=rows,
            fields=fields,
            quantity_index=quantity_index,
            order_lines=order_lines,
        )
        mapped_count = _count_non_empty_quantity_cells(
            rows=rows,
            quantity_index=quantity_index,
        )
        mapped_mode = "identity"
    elif isinstance(ocr_payload, dict):
        if payload_rows:
            match_stats = _apply_payload_quantities_numeric_only(
                rows=rows,
                fields=fields,
                quantity_index=quantity_index,
                payload_rows=payload_rows,
                payload_unstructured_qty=payload_unstructured_qty,
                allow_heuristics=False,
                enable_daypart_consensus=False,
                explicit_quantity_pairs=payload_explicit_quantity_pairs,
                overlay_structural_fields_from_sheet_rows=True,
                allow_row_index_fallback=False,
                allow_span_copy=False,
            )
            mapped_count = _count_non_empty_quantity_cells(
                rows=rows,
                quantity_index=quantity_index,
            )
            if mapped_count > 0:
                mapped_mode = "payload_row"
        else:
            match_stats = None
    else:
        match_stats = None
    if payload_rows:
        rows = _overlay_payload_aux_cells_onto_sheet_rows(
            rows=rows,
            fields=fields,
            header=_sheet_header_from_template(fields, template),
            payload_rows=payload_rows,
            raw_payload=ocr_payload if isinstance(ocr_payload, dict) else None,
            template=template,
        )

    sheet_payload = {
        "order_id": order_id,
        "facility_id": facility_id,
        "week_id": resolved_week_id,
        "resolved_week_id": resolved_week_id,
        "fields": fields,
        "header": header[: len(fields)],
        "rows": [list(item.get("values") or []) for item in rows],
        "row_ids": [str(item.get("row_id") or f"row-{idx + 1}") for idx, item in enumerate(rows)],
        "quantity_column_count": len([field for field in fields if field.startswith("qty.")]),
        "source": source if mapped_mode == "blank" else f"{source}+{mapped_mode}",
        "seed_source": source,
        "enrichment_source": (
            "order_lines"
            if mapped_mode == "identity"
            else "ocr_payload"
            if mapped_mode == "payload_row"
            else None
        ),
        "warnings": _replace_menu_blocker_tokens(
            [],
            canonical_code=_canonical_menu_diagnostic_code(menu_diagnostics),
        ),
        "blockers": [],
        "draft_state": "draft_ready",
        "base_template_resolution_id": effective_template_id,
        "base_evidence_run_id": str((base_evidence_run or {}).get("id") or "").strip() or None,
        "menu_diagnostics": menu_diagnostics,
        "row_diagnostics": [],
        "projection_diagnostics": {},
        "cell_issues": [],
        "issue_summary": {
            "review_required_cell_count": 0,
            "issue_codes": [],
        },
        "trace": {
            "rows": _build_sheet_trace_rows(
                rows=rows,
                fields=fields,
                quantity_index=quantity_index,
                source=source,
                mapped_mode=mapped_mode,
                quantity_value_source="order_lines" if has_order_lines else None,
            ),
            "mapped_mode": mapped_mode,
            "mapped_count": mapped_count,
        },
    }
    if mapped_mode == "payload_row" and isinstance(match_stats, dict):
        sheet_payload["projection_diagnostics"] = {"payload_match_stats": match_stats}
    return sheet_payload, None


def build_initial_sheet_draft(order_id: str) -> Optional[dict]:
    # Canonical unpersisted current state must be resolved through the same
    # sheet/read paths that drive Step2 and operator-visible OCR review.
    # Otherwise `current_sheet_context` can drift from `get_ocr_sheet`.
    draft_payload, draft_error = get_ocr_sheet(
        order_id,
        use_saved_draft=False,
    )
    if isinstance(draft_payload, dict):
        return draft_payload
    if draft_error in _RECOVERABLE_OCR_SHEET_ERRORS:
        recovered_payload, recover_error = build_recoverable_ocr_sheet_payload(
            order_id,
            draft_error,
            use_saved_draft=False,
        )
        if recover_error is None and isinstance(recovered_payload, dict):
            return recovered_payload
    order_payload = get_order_by_id(order_id)
    facility_id = str((order_payload or {}).get("facility") or "").strip() or None
    resolved_week_id = (
        str((order_payload or {}).get("persisted_week_value") or "").strip()
        or str((order_payload or {}).get("week_value") or "").strip()
        or str((order_payload or {}).get("week") or "").strip()
        or None
    )
    if draft_error:
        return _build_blocked_sheet_payload(
            order_id=order_id,
            facility_id=facility_id,
            week_id=resolved_week_id,
            blockers=[draft_error],
            source="weekly_menu_blocked",
        )
    return None


def _build_transient_draft_record(
    order_id: str,
    sheet_payload: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(sheet_payload, dict):
        return None
    blockers = _dedupe_str_tokens(sheet_payload.get("blockers") or [])
    warnings = _dedupe_str_tokens(sheet_payload.get("warnings") or [])
    draft_state = str(
        sheet_payload.get("draft_state")
        or ("draft_blocked" if blockers else "draft_ready")
    ).strip() or ("draft_blocked" if blockers else "draft_ready")
    return {
        "id": None,
        "order_id": order_id,
        "base_evidence_run_id": sheet_payload.get("base_evidence_run_id"),
        "base_template_resolution_id": str(sheet_payload.get("base_template_resolution_id") or "").strip() or None,
        "base_menu_snapshot_id": None,
        "draft_sheet_json": sheet_payload,
        "draft_state": draft_state,
        "blockers_json": blockers,
        "warnings_json": warnings,
        "latest_patch_candidate_id": None,
        "edited_by": None,
        "edited_at": None,
        "created_at": None,
    }


def candidate_sheet_state(
    order_id: str,
    *,
    candidate_evidence_run_id: str | None,
    current_sheet_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    normalized_candidate_evidence_run_id = str(candidate_evidence_run_id or "").strip() or None
    current_context = (
        current_sheet_context
        if isinstance(current_sheet_context, dict)
        else get_current_sheet_context(
            order_id,
            refresh_draft_from_semantic=True,
            upgrade_generic_from_sheet=True,
            backfill_from_revision=False,
        )
    )
    current_sheet_revision_id = (
        _current_sheet_revision_id_from_payload(current_context)
        or _current_sheet_revision_id(order_id=order_id)
    )
    current_payload = (
        flatten_current_sheet_payload(order_id, current_context, include_meta=False)
        if isinstance(current_context, dict)
        else None
    )
    current_base_evidence_run_id = (
        str((current_context or {}).get("base_evidence_run_id") or "").strip()
        or str((current_payload or {}).get("base_evidence_run_id") or "").strip()
        or None
    )
    result: dict[str, Any] = {
        "candidate_evidence_run_id": normalized_candidate_evidence_run_id,
        "current_sheet_revision_id": current_sheet_revision_id or None,
        "current_base_evidence_run_id": current_base_evidence_run_id,
        "candidate_preview_available": False,
        "candidate_preview_error": "candidate_not_found" if not normalized_candidate_evidence_run_id else None,
        "candidate_has_meaningful_diff": False,
        "candidate_preview_draft": None,
    }
    if not normalized_candidate_evidence_run_id:
        return result
    contract = resolve_candidate_evidence_preview_contract(
        order_id,
        candidate_evidence_run_id=normalized_candidate_evidence_run_id,
        current_sheet_context=current_context,
    )
    result["candidate_preview_available"] = bool(contract.get("previewable"))
    result["candidate_preview_error"] = str(contract.get("error") or "").strip() or None
    result["candidate_has_meaningful_diff"] = bool(contract.get("has_material_diff"))
    preview_draft = contract.get("preview_draft") if isinstance(contract.get("preview_draft"), dict) else None
    if isinstance(preview_draft, dict):
        draft_payload = (
            preview_draft.get("draft_sheet_json")
            if isinstance(preview_draft.get("draft_sheet_json"), dict)
            else None
        )
        preview_base_evidence_run_id = (
            str(preview_draft.get("base_evidence_run_id") or "").strip()
            or str((draft_payload or {}).get("base_evidence_run_id") or "").strip()
            or normalized_candidate_evidence_run_id
            or None
        )
        if preview_base_evidence_run_id:
            preview_draft["base_evidence_run_id"] = preview_base_evidence_run_id
            if isinstance(draft_payload, dict):
                draft_payload["base_evidence_run_id"] = preview_base_evidence_run_id
        preview_draft["current_sheet_revision_id"] = current_sheet_revision_id or None
    result["candidate_preview_draft"] = preview_draft
    return result


def _draft_is_reparse_candidate_only(draft: dict[str, Any] | None) -> bool:
    if not isinstance(draft, dict):
        return False
    draft_payload = (
        draft.get("draft_sheet_json")
        if isinstance(draft.get("draft_sheet_json"), dict)
        else draft
    )
    source = str((draft_payload or {}).get("source") or "").strip()
    edited_by = str(draft.get("edited_by") or "").strip()
    latest_patch_candidate_id = str(draft.get("latest_patch_candidate_id") or "").strip()
    return (
        source == "reparse_candidate"
        or edited_by == "reparse-reject-candidate"
        or latest_patch_candidate_id == "reparse-candidate"
    )


